export default [{"id":865,"question":"من القضايا التي تُثير المُناقشات في بعض الأحيان: التوسل، خاصَّةً بجاه وقدر رسول الله ﷺ وبعض الأولياء والصَّالحين الأموات، فهل يجوز ذلك أم يحظر؟ أفيدونا وفَّقكم الله.","title":"حكم التوسل بجاه النبي وقبور الصالحين","answer":"الجواب: التوسل بالجاه محظورٌ عند جمهور أهل العلم؛ لأنه ليس من المشروعات، ولم يأتِ عن النبي ﷺ ولا عن أصحابه ما يدل على جوازه، فهو من البدع، والدعاء والوسائل من العبادات، فلا يجوز أن يتّخذ من الوسائل إلا ما شرعه الله، فالتوسل بجاه النبي، أو بجاه فلانٍ، أو بحقِّ الأنبياء، أو بحقِّ المؤمنين؛ لا أصلَ له، بل هو من البدعة في الدعاء، وإنما التوسل يكون بأسماء الله وصفاته، كما قال : وَلِلَّهِ الْأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180].\nوفي الحديث: اللهم إني أسألك بأني أشهد أنَّك أنت الله لا إله إلا أنت، وحديث أصحاب الغار، التوسل بأعمالهم الطيبة: واحد توسَّل ببرِّ والديه، والثاني توسَّل بعفَّته عن الزنا، والثالث توسَّل بأداء الأمانة؛ لا بأس، أما التوسل بجاه فلانٍ وحقِّ فلانٍ؛ هذا بدعة، هذا هو الذي عليه جمهورُ أهل العلم، وليس بشركٍ، لكنه بدعة من وسائل الشرك.","link":"https://binbaz.org.sa/fatwas/20906/حكم-التوسل-بجاه-النبي-وقبور-الصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0701ما حكم التوسل بجاه وقبر الرسول صلى الله عليه وسلم وبعض الأولياء والصالحين والأموات؟ ابن باز.mp3","categories":["شروح الحديث","التوسل والشفاعة"]},{"id":1246,"question":"ما حكم التَّوسل بجاه النبي ﷺ، علمًا بأن أخي يقول: إن شيخ الإسلام ابن تيمية وشيخ الإسلام محمد بن عبدالوهاب وسماحة الشيخ عبدالعزيز بن باز يقولون بأنها مسألةٌ خلافيةٌ بين أهل العلم، والراجح أنه مكروه كراهة تنزيهٍ؟ فما قول فضيلتكم في هذا الأمر وجزاكم الله خيرًا؟","title":"ما حكم التوسل بجاه الأنبياء؟","answer":"الجواب:\nالتَّوسل بجاه النبي ﷺ، وبجاه الأنبياء، أو بحقِّ النبي، أو بحقِّ الأنبياء؛ بدعة في الدعاء، ومنكر لا يجوز، وهذا الذي قاله جمهورُ أهل العلم، وهو قول شيخ الإسلام ابن تيمية وابن القيم وأئمَّة الدعوة، كالشيخ محمد بن عبدالوهاب وغيرهم؛ لأنَّ الرسول ما كان يُعلِّم الناسَ هذا، يقول الله: وَلِلَّهِ الْأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180]، ما قال: فادعوه بجاه فلان، أو بحقِّ فلان، قال: فَادْعُوهُ بِهَا.\nوالرسول كان يدعو الله بأسمائه، يقول للصديق لما قال: يا رسول الله، علمني دعاء أدعو به في صلاتي، قال: قل: اللهم إني ظلمتُ نفسي ظلمًا كثيرًا، ولا يغفر الذنوبَ إلا أنت، فاغفر لي مغفرةً من عندك وارحمني، إنَّك أنت الغفور الرحيم، ما قال: ادعُ الله بجاهي.\nوالحديث الذي يقول: توسَّلوا بجاهي، فإنَّ جاهي عند الله عظيم هذا موضوعٌ، أجمع العلماء على أنه موضوعٌ مكذوبٌ عن النبي ﷺ.\nوقال لمعاذٍ: يا معاذ، والله إني لأحبُّك، لا تدعنَّ أن تقول دبر كل صلاةٍ: اللهم أعني على ذكرك وشُكرك وحُسن عبادتك، ما قال: بجاه نبيك، أو بحقِّ نبيك، فالدعاء عبادة، والوسائل عبادة، لا بد فيها من دليلٍ: قال الله، وقال رسوله.\nيُروى عن بعض العلماء أنَّهم أجازوا ذلك، واحتجُّوا بحديث الأعمى، قالوا: إنَّ الأعمى علَّمه النبيُّ لما شكى، علَّمه النبيُّ ﷺ قال: توضأ وصلِّ ركعتين، ثم قل: اللهم إني أسألك وأتوجه إليك بنبيك محمدٍ نبي الرحمة، اللهم إني أتوجه إليك بنبيك في حاجتي هذه أن تُقضى، اللهم شفِّعه فيَّ، وشفعني فيه، قال بعضُهم: وذكره بعضُهم عن العز ابن عبدالسلام، أنَّ هذا يدل على التوسل بالنبي خاصَّةً.\nقال العلماء: الجواب عن هذا أن هذا توسّل بدعائه؛ لأنه حيٌّ، أمره أن يدعوه، هذا توسّل بدعاء النبي، ولهذا قال: اللهم شفّعه فيَّ، فقوله: اللهم إني أتوجه إليك وأتوسّل بنبيك محمدٍ يعني: بدعائه لي وشفاعته لي، ثم قال: اللهم شفّعه فيَّ، وشفعني فيه يعني: اللهم اقبل دعاءه فيَّ، ودعائي فيه، ولم يقل للناس: ادعوا الله بشفاعتي، بجاهي، أو بحقِّي، لا، بل يُدعى الربُّ بأسمائه وصفاته وبالأعمال الصَّالحة، كأن تقول: \"اللهم إني أسألك بمحبتي لك، أو بمحبتي لنبيك ﷺ، أو باتباعي لنبيك محمد ﷺ\"، هذا طيبٌ، توسل بالأعمال أو بالصفات: \"اللهم إني أسألك بعلمك الغيب، بمحبتك، بكرمك، بجودك\"، توسل بصفات الله، أو بأسمائه، كله حقٌّ.\nفالتوسل بأسماء الله وصفاته وتوحيده وبالأعمال الصَّالحة كله حقٌّ، كما قال تعالى: وَلِلَّهِ الْأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180]، وعلم الصديق يقول: اللهم إني ظلمتُ نفسي ظلمًا كثيرًا، ولا يغفر الذنوبَ إلا أنت، فاغفر لي مغفرةً من عندك، وارحمني، إنك أنت الغفور الرحيم، هذا توسّل بأسماء الله وصفاته، وهكذا في الحديث: اللهم إني أسألك بأني أشهد أنَّك أنت الله لا إله إلا أنت، الأحد الصمد، الذي لم يلد ولم يولد، ولم يكن له كفوًا أحد، هذا توسل بصفات الله وتوحيده، كله حقٌّ.\nوهكذا أصحاب الغار الثلاثة الذين أخبر عنهم النبيُّ ﷺ في \"الصحيحين\" أنهم آواهم المبيت، وفي لفظٍ: المطر إلى غارٍ، جاؤوا إلى غارٍ في الليل بسبب المبيت والمطر، فدخلوا فيه، فانحدرت عليهم صخرةٌ عظيمةٌ سُدَّت الغارَ، فما استطاعوا أن يخرجوا ولا أن يدفعوها، فقالوا فيما بينهم: لن يُنجيكم من هذه المصيبة إلا أن تدعوا الله بصالح أعمالكم، فقال أحدُهم: اللهم إنه كان لي أبوان شيخان كبيران، وكنتُ لا أغبق قبلهما أهلًا ولا مالًا، يعني: اللبن الحليب، الغبوق: لبن يشربونه بعد العشاء، فنأى بي طلبُ الشجر ذات ليلةٍ، فلم أرح عليهما إلا وقد ناما -صيف عليهم- فوقفتُ بالقدح على يدي أنتظر استيقاظهما، وكرهتُ أن أُوقظهما، والصِّبية يتضاغون تحت قدمي –يعني: يُريدون الشراب- فلم أزل أنتظرهما حتى برق الصبحُ، اللهم إن كنت تعلم أني فعلتُ ذلك ابتغاء وجهك فافرج عنا ما نحن فيه، فانفرجت الصَّخرةُ بعض الشيء، لكن لا يستطيعون الخروج.\nثم قال الثاني: اللهم إنه كانت لي ابنةُ عمٍّ كنتُ أحبها كأشدّ ما يُحب الرجال النساء، فطلبتُها لنفسي، فاعتذرت عليَّ، طلبها للزنا فأبت، فألمت بها حاجةٌ –يعني: فقرًا- فجاءت إليه تقول: يا عبدالله، أعطني كذا وكذا، أنا محتاجة، فقال: لا، حتى تُمكنيني من نفسك، فعند الضَّرورة وافقت على أن يُعطيها مئةً وعشرين دينارًا، مئة جنيه وعشرين جنيهًا ذهبًا حتى تُمكّنه من نفسها، ففعل، فلما جلس بين رجليها قالت: يا عبدالله، اتَّق الله ولا تفضّ الخاتم إلا بحقِّه، فخاف الرجلُ وقام وتركها وذهبها، ولم يُجامعها، ثم قال: اللهم إن كنتَ تعلم أني فعلتُ هذا ابتغاء وجهك فافرج عنا ما نحن فيه، فانفرجت الصخرةُ بعض الشيء، لكن لا يستطيعون الخروج.\nفقال الثالث: اللهم إنه كان لي أُجراء، فأعطيتُ كلَّ أجيرٍ حقَّه، إلا أجيرًا واحدًا ترك عندي حقَّه، فثمرته له، واشتريتُ منه إبلًا وبقرًا وغنمًا ورقيقًا، ثم جاء يطلب حقَّه فقلتُ: كل هذا من حقِّك، هذه الإبل، وهذا البقر، وهذه الغنم، وهذا الرقيق؛ كله من حقِّك، وحقّه كان أرزًا أو ذرةً، شيء من طعامٍ، فباعه وثَمَّره هذا حقّك، فساقه كلَّه ولم يدع منه شيئًا، اللهم إن كنتَ تعلم أني فعلتُ هذا ابتغاء وجهك فافرج عنا ما نحن فيه، فانفرجت الصخرةُ وخرجوا.\nهذه من آيات الله، أراهم الله العبرة، ودعوا ربَّهم بهذه الأعمال الصَّالحة، فهذا لا بأس به، التوسل إلى الله بأعمالك الصَّالحة: بتوحيد الله، بأسمائه وصفاته، بمحبَّتك له؛ لأنَّ هذا عملٌ صالحٌ، المحبَّة لنبيه والمؤمنين عملٌ صالحٌ، هذا لا بأس، أما بالجاه والحقّ: بجاه فلان، أو بحق فلان، فهذا ليس وسيلةً، بل هذا بدعة، لا يجوز التَّوسل بها على الصحيح الذي عليه جمهورُ أهل العلم.\nوالله ولي التوفيق.","link":"https://binbaz.org.sa/fatwas/21308/ما-حكم-التوسل-بجاه-الانبياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1051ما حكم التوسل بجاه النبي صلى الله عليه وسلم؟ ابن باز فتاوى.mp3","categories":["شروح الحديث","التوسل والشفاعة"]},{"id":1443,"question":"الشفاعة خاصَّة بأمة المسلمين، وبالنسبة لموسى وعيسى هل ما يشفعون لأُمَمِهم؟","title":"أنواع الشفاعة يوم القيامة ولمن تكون؟","answer":"الجواب:\nبلى، ولكن هذا الموقف للجميع، هذه شفاعة الموقف ودخول الجنة للجميع. وأما الشفاعة الخاصة فكل نبيٍّ له شفاعة، لكن يوم القيامة الناس يشتد بهم الأمر: ماذا يفعلون من الكرب حتى يُقْضَى بينهم؟ أول شيءٍ يذهبون إلى آدم -أبي البشر- ويُحيلهم آدمُ إلى نوحٍ، ونوحٌ يُحيلهم إلى إبراهيم، وإبراهيمُ يُحيلهم إلى موسى، وموسى يُحيلهم إلى عيسى، وعيسى يُحيلهم إلى النبي ﷺ، فيتقدَّم ويشفع في أهل الموقف حتى يُقْضَى بينهم.\nالشفاعة الثانية العظيمة تكون في الجنة، فإذا انتهى الحسابُ وبقي دخول أهل الجنة الجنة؛ فإنهم كذلك يطلبون الشفاعة –أهل الجنة- في أن يُوَجَّهوا إلى الجنة، وأن تُفْتَح أبوابها لإظهار شأنهم ووضعهم، فيأتون آدم، ثم نوحًا، ثم إبراهيم .. إلى آخره، فتنتهي إلى النبي ﷺ، ويشفع لهم في دخولهم الجنة.\nس: النبي الذي يأتي وحده يوم القيامة هل له شفاعة؟\nج: ما تبعه أحدٌ -نسأل الله السلامة- الذي مات أو قتلوه ما في شفاعة، كفَّارٌ كلهم.\nس: بالنسبة لشفاعة النبي ﷺ لأهل النار: هل يدخل فيها الأممُ الباقية؟\nج: عُصاة أمته فقط.\nس: أمته فقط؟\nج: نعم أمته.\nس: وبقية الأنبياء يشفعون أيضًا؟\nج: نعم يشفعون لأممهم، والأخيار، والمؤمنون، والملائكة.\nس: بالنسبة للشفاعة الأولى أوَّلًا يبدأ بها النبيُّ ﷺ؟\nج: نعم في أهل الموقف حتى يُقْضَى بينهم، ثم في أهل الجنة حتى يدخلوها، ثم بعد ذلك فيمَن دخل النار أن  يُخرج منها –العُصاة- فيشفع شفاعات عديدة. س: الحوض قبل الصراط؟\nج: الحوض قبل الصراط وقبل الحساب والجزاء، يرده الناسُ يوم القيامة وهم ظِمَاء.\nس: بالنسبة للشفاعة الأولى هل يشترك بقيةُ الأنبياء مع نبينا محمدٍ؟\nج: لا، وحده، هو الذي يسجد تحت العرش، ثم يحمد الله بمحامد، ثم يُقال له: ارفع رأسك.","link":"https://binbaz.org.sa/fatwas/21539/انواع-الشفاعة-يوم-القيامة-ولمن-تكون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الشفاعة.mp3","categories":["شروح الحديث","التوسل والشفاعة"]},{"id":2603,"question":"بالنسبة لحديث الشفاعة: تأخير أهل الإيمان طلب الشفاعة من الرسول ﷺ ومرورهم على الأنبياء؟","title":"حكمة طلب شفاعة الأنبياء قبل النبي","answer":"الجواب: هذا علمنا إياه، عرفه المسلمون، عرف المسلمون النصوص، الشفاعة تنتهي إليه عليه الصلاة والسلام؛ لإظهار فضله وعُلُو منزلته بين الخلائق يوم القيامة.","link":"https://binbaz.org.sa/fatwas/22737/حكمة-طلب-شفاعة-الانبياء-قبل-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكمة في تأخير أهل الإيمان طلب الشفاعة من الرسول ومرورهم على الأنبياء.mp3","categories":["شروح الحديث","التوسل والشفاعة"]},{"id":2854,"question":"المُكثِر من الصلاة (على النبي ﷺ) مِنْ أوْلى الناس بشفاعة النبي ﷺ: الشفاعة للعرض يا شيخ، أو الشفاعة لدخول الجنة؟","title":"ما الشفاعة الخاصة بأصحاب الصلاة والتسليم؟","answer":"الجواب: عامة، لكن المهم دخول الجنة، وإلا الشفاعة العظمى تعم الجميع الكفار والمسلمين، شفاعته في أن يقضى بينهم، لكن الشفاعات الأخرى شفاعات في ثقل الميزان، في عظم الأجر، وفي دخول الجنة والنجاة من النار، هي شفاعات أخرى، يشفع شفاعات عديدة عليه الصلاة والسلام في أهل النار من العصاة.\nس: هذه يختص بها صاحب الصلاة على النبي؟\nالشيخ: نعم المسلم، أما الكافر أعماله باطلة، صلاته وغيرها وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] ما ينفع الشرك.","link":"https://binbaz.org.sa/fatwas/23007/ما-الشفاعة-الخاصة-باصحاب-الصلاة-والتسليم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للنبي الشفاعة العظمى أو شفاعة دخول الجنة.mp3","categories":["التوسل والشفاعة"]},{"id":3073,"question":"هل يجوز السؤال بوجه الله؟","title":"ما حكم السؤال بوجه الله تعالى؟","answer":"الجواب: ما ينبغي السؤال بوجه الله، ولا السؤال بالله، إلا للحاجة.\nالسؤال: والإجابة يا شيخ، إذا سأله بوجه الله هل يُجيبه؟\nالشيخ: إذا سأل بوجه الله فأعطوه؛ لحديث: من سأل بوجه الله فأعطوه إذا تيسّر، لكن يُعَلّم ألا يسأل بوجه الله. يُنْصَح ألا يسأل بوجه الله.","link":"https://binbaz.org.sa/fatwas/23233/ما-حكم-السوال-بوجه-الله-تعالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم السؤال بوجه الله.mp3","categories":["التوسل والشفاعة"]},{"id":4235,"question":"بعض الناس أحسن الله إليك إذا أحبك قال: بحق جاه النبي ﷺ أن تقلط عندي، ما حكم هذه المقولة؟","title":"حكم قول \"بحق جاه النبي\"","answer":"الجواب: هذا من وسائل الشرك، جاه النبي وحق جاه النبي وبالنبي، هذه من وسائل الشرك، يجب الحذر منها.","link":"https://binbaz.org.sa/fatwas/24502/حكم-قول-بحق-جاه-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قول بحق جاه النبي..mp3","categories":["التوسل والشفاعة"]},{"id":4290,"question":"شفاعة النبي ﷺ للكفار لتخفيف العذاب فقط؟","title":"هل توجد شفاعة من النبي للكفار؟","answer":"الجواب: في أبي طالب خاصة التخفيف.","link":"https://binbaz.org.sa/fatwas/24562/هل-توجد-شفاعة-من-النبي-للكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شفاعة النبي للكفار.mp3","categories":["التوسل والشفاعة"]},{"id":4293,"question":"اللي ينكر شفاعة الرسول ﷺ يصير كافرًا؟","title":"ما حكم من ينكر شفاعة النبي عليه الصلاة والسلام؟","answer":"الجواب: يَكْفُر، نعم.","link":"https://binbaz.org.sa/fatwas/24565/ما-حكم-من-ينكر-شفاعة-النبي-عليه-الصلاة-والسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من ينكر شفاعة الرسول.mp3","categories":["التوسل والشفاعة"]},{"id":4295,"question":"من الذين لا تشملهم الشفاعة؟","title":"من الذين لا تشملهم الشفاعة؟","answer":"الجواب: الكفار، ويبقى بقية من العصاة ما تشملهم الشفاعات كلها، يخرجهم الله بغير شفاعة؛ فضلًا منه سبحانه.","link":"https://binbaz.org.sa/fatwas/24567/من-الذين-لا-تشملهم-الشفاعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من الذين لا تشملهم الشفاعة.mp3","categories":["التوسل والشفاعة"]},{"id":4316,"question":"الدعاء بجاه النبي ﷺ؟","title":"هل يجوز التوسل بجاه النبي عليه الصلاة والسلام؟","answer":"الجواب: من الوسائل، ما يجوز اللهم إني أسألك بجاه النبي، هذا ما يجوز، أو اللهم إني أسألك بنبيك أو بالصالحين أو بجاه الصالحين.","link":"https://binbaz.org.sa/fatwas/24590/هل-يجوز-التوسل-بجاه-النبي-عليه-الصلاة-والسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الدعاء بجاه النبي.mp3","categories":["التوسل والشفاعة"]},{"id":5348,"question":"أعوذ بعزة الله؟","title":"ما حكم التعوُّذ بعزة الله والتوسُّل بها؟","answer":"الجواب: هذا تعوُّذ وتوسُّل: أعوذ برضاك من سخطك، وبعفوك من عقوبتك، بعزة الله وقُدرته، لا يقال: يا عزة الله انصرينا، نقل الشيخُ تقي الدين ابن تيمية إجماعَ العلماء على منع ذلك: أن الصِّفات لا تُدعى، إنما الدَّعوة للأسماء، يُدعى بأسمائه . س: يُتوسل بها؟ ج: التوسل لا بأس بالصِّفات، والتَّعوذ بالصِّفات: أعوذ بكلمات الله التامات، أعوذ برضا الله من سخطه، برضاك من سخطك، لكن لا يقال: يا رضا الله، يا عفو الله، يا علم الله، يا سمع الله، لا.  يقول: يا الله، يا سميع، يا عليم، يا رؤوف، يا رحيم، اغفر لنا وارحمنا، يُدعى بأسمائه : وَلِلَّهِ الْأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180].[1]","link":"https://binbaz.org.sa/fatwas/31040/ما-حكم-التعوذ-بعزة-الله-والتوسل-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fat7_majed 003.mp3","categories":["التوسل والشفاعة"]},{"id":5360,"question":"في نشرةٍ بعنوان: \"مسائل مهمة في العقيدة الإسلامية\" جاء فيها كلمة: ويجوز التَّوسل بحبِّ الله لرسوله ﷺ وأوليائه، وحبنا للرسول ﷺ والأولياء؛ لأن حبَّنا لهم من العمل الصالح، فنقول مثلًا: اللهم بحبك لرسولك وأوليائك انصرنا، وبحبك لرسولك وأوليائك اشفنا.","title":"ما حكم التَّوسل بحبِّ الله لرسوله ولأوليائه؟","answer":"الجواب: نعم، لا بأس بالتوسل بحبِّ الله، نعم، من صفاته جلَّ وعلا: اللهم إني أسألك بحبك لأوليائك ولرسولك ولأهل طاعتك، اللهم إني أسألك بحبي لرسولك، بحبي لك، بحبي لأوليائك المتقين. هذا توسل بصفات الله: وَلِلَّهِ الْأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180]. س: الثاني ما هو بالعمل الصالح؟ ج: ماذا؟ س: بحبي لرسولك: ليس من العمل الصالح؟ ج: هذا عمل صالح. س: لكن بمحبَّته هو لرسله وأوليائه؟ ج: التوسل بمحبة الله لأوليائه، والتوسل بحبنا لله ولرسوله، كله حقّ، الأول توسل بصفات الله، والثاني توسل بأعمالنا الصالحة، مثل: وسيلة أهل الغار.[1]","link":"https://binbaz.org.sa/fatwas/31060/ما-حكم-التوسل-بحب-الله-لرسوله-ولاولياىه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/tawheed_ibnkhozaima002.mp3","categories":["التوسل والشفاعة"]},{"id":5508,"question":"رضا الله عن المشفوع له، أليست شرطًا من شروط الشَّفاعة؟","title":"هل يلزم رضا الله عن المشفوع له؟","answer":"الجواب: بلى. س: إذن شفاعة النبي ﷺ لعمه وقبول الله لذلك؟ ج: هذه شفاعة خاصَّة، شفع له، ولكن لم يقبل منه، فأنزل الله تعالى: مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُولِي قُرْبَى [التوبة:113]، وذلك قبل أن يعلم، فلما علم ذلك ترك الشَّفاعة، لما شفع قال: لأستغفرنَّ لك ما لم أُنْهَ عنك، هكذا في البخاري، فلما نُهي عنه كفَّ عن ذلك. س: أبو النبي عليه الصلاة والسَّلام؟ ج: أبو النبي وأمه كانا في الجاهلية، ماتا في الجاهلية، وفي الحديث: إنَّ أبي وأباك في النار، وسأل النبي ﷺ ربَّه أن يستغفر لأمه فلم يُؤذن له؛ لأنها ماتت في الجاهلية على دين قومها؛ عبادة الأوثان. س: ليسوا من أهل الفترة؟ ج: ظاهر الحديث أنها من أهل الكفر؛ لأنه استأذن في أن يستغفر لها فلم يُؤذن له، يحتمل أن تكون من أهل الفترة، لكن جاء في بعض الروايات أنها من أهل النار، كحديث إن أبي وأباك في النار، رواه مسلم في الصحيح. س: هل قامت عليهم الحُجَّة؟ ج: لعله جاءهم من دين إبراهيم ما أقام عليهم الحُجَّة.[1]","link":"https://binbaz.org.sa/fatwas/31440/هل-يلزم-رضا-الله-عن-المشفوع-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 023.mp3","categories":["التوسل والشفاعة"]},{"id":5510,"question":"الشَّفاعة الخاصَّة للنبي ﷺ ما هي؟","title":"ما الشَّفاعة الخاصَّة للنبي عليه الصلاة والسلام؟","answer":"الجواب: الشفاعة لأبي طالب، فقط هذه الخاصة به، وشفاعتان خاصتان: الشفاعة لأهل الموقف، والشفاعة في أهل الكبائر، هذه خاصة بالنبي ﷺ. الشفاعة في أهل الموقف هذه خاصة، يتأخر عنها جميعُ الرسل: نوح وإبراهيم وموسى وعيسى، كلهم يتأخرون، هذه خاصة بمحمدٍ ﷺ. والشفاعة الثانية في أهل الجنة، في دخول الجنة، هو الذي يستفتح لهم باب الجنة، هذه ثنتان. وهناك ثالثة خاصّة بأبي طالب، شفاعة في أن يُخفف عنه، - نسأل الله العافية- فإنه كان في غمرات من النار، فشفع له فصار في ضحضاح من النار، يغلى منها دماغه.[1]","link":"https://binbaz.org.sa/fatwas/31442/ما-الشفاعة-الخاصة-للنبي-عليه-الصلاة-والسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 025.mp3","categories":["التوسل والشفاعة"]},{"id":5959,"question":"أحسن الله إليك، إذا قال: أسألك بنور وجهك الذي أشرقت له؟","title":"حكم قول: أسألك بنور وجهك الذي أشرقت له..","answer":"الجواب: ما فيه بأس، هذا ورد في بعض الأحاديث: أسألك بنور وجهك الذي أشرقت له السماوات، والأرض لا بأس به، نوره عظيم  به أشرقت الدنيا.","link":"https://binbaz.org.sa/fatwas/1326/حكم-قول-اسالك-بنور-وجهك-الذي-اشرقت-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_295.mp3","categories":["شروح الحديث","التوسل والشفاعة"]},{"id":6146,"question":"هل يجوز من يدعو رب العالمين أن يقول: بحق محمد عليك؟","title":"حكم قول بحق محمد عليك في الدعاء","answer":"الجواب: ما ينبغي، لا يقول: بحق محمد، ولا بجاه محمد، ولا بحق الأنبياء، يتوسل بأسماء الله، وصفاته، بأنك الرحمن، بأنك الرحيم، بأنك رب العالمين، أو بالأعمال الصالحة، يسأل الله بإيمانه به، وإيمانه بنبيه ﷺ وتوحيده له، وإخلاصه، هذه الوسيلة: الأسماء الحسنى، وصفات الله، والأعمال الصالحات، أما التوسل بجاه فلان، وحق فلان؛ فهذا منكر.","link":"https://binbaz.org.sa/fatwas/1594/حكم-قول-بحق-محمد-عليك-في-الدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_488.mp3","categories":["التوسل والشفاعة","القرآن وعلومه"]},{"id":6970,"question":"قرأت في أحد رسائل طلبة العلم في تعريفه للوسيلة: بأنها دعاء الله بواسطة، فهل هذه العبارة صحيحة، وخاصة أنه قد يلبس، ويزين للعوام من دعاة السوء بأن دعاء الله بواسطة كجاه النبي، وجاه الأولياء، وكراماتهم، وغير ذلك من الوسائط، مع أن الله قال: وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ [البقرة:186] نرجو توضيح معنى الوسيلة لغة، وشرعًا، وما هي الوسيلة التي يتقرب بها إلى الله؟","title":"التوسل المشروع والممنوع","answer":"الجواب: \n\nهذا غلط، هذا تفسير الوسيلة غلط، الوسيلة فسرها العلماء بأنها قربة بالطاعة، توسل بالطاعات، قال -جل وعلا-: يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ، وَابْتَغُوا إِلَيْهِ الْوَسِيلَةَ [المائدة:35] أي القربة إليه بطاعته، كما قال العلماء: كابن جرير، والبغوي، وابن كثير، وغيرهم، معنى الوسيلة القربة إليه بالطاعة.\n\nوهكذا القول الثاني: أُولَئِكَ الَّذِينَ يَدْعُونَ يَبْتَغُونَ إِلَى رَبِّهِمُ الْوَسِيلَةَ [الإسراء:57] يعني القربة إليه بالطاعة، بالصلاة، بالصوم، بالدعاء...\n\nاللهم إني أسألك بجاه فلان، أو بحق فلان، أو بنبيك فلان، هذا ليس بمشروع، ولم يأت به شرع، وليس من الوسيلة التي شرعها الله -جل وعلا-فالذي فسر الوسيلة أنها التوسل بجاه الأنبياء، أو بجاه الملائكة، أو بجاه الأولياء؛ فقد غلط في هذا، وأتى بشيء ما عرفه العلماء، ولا ذكره أهل العلم، والتحقيق المعروفون بالاستقامة، وإنما هذا مما قاله بعض قاصري العلم، وبعض المتأخرين.\n\nالسؤال: ذكر هذا صاحب الرسالة، قال: إن الوسيلة هي دعاء الله بواسطة، ثم علق عليها بقوله: \"اللهم بحبنا لكم، وحبنا لرسول الله\".\n\nالجواب: هذا توسل بالعمل الصالح، التوسل إلى الله بحب الرسول من العمل الصالح، فإذا قال: اللهم إني أسألك بحبي لأنبيائك، بحبي لنبيك، بإيماني بك، باتباعي لشرعك، بطاعتي لرسولك هذا توسل بالأعمال الصالحة، فالتوسل إلى الله بالطاعات، والأعمال الصالحات هذه هي الوسيلة.\n\nومن ذلك التوسل بحب الله، التوسل بحب رسوله -عليه الصلاة، والسلام- ومثل ذلك ما توسل به أصحاب الغار لما انطبقت عليهم الصخرة وهم ثلاثة، ولم يستطيعوا دفعها؛ توسلوا إلى الله بأعمالهم الصالحة، واحد توسل ببره لوالديه، وواحد توسل بعفته عن الزنا، والثالث توسل بأدائه الأمانة.\n\nفالتوسل بالأعمال الصالحات هو الوسيلة الشرعية، أما التوسل بجاه فلان، أو حق فلان؛ فليس من الأعمال الصالحة.\n\nالسؤال: تفسير الوسيلة بأنها الدعاء إلى الله بواسطة، هذه جائزة؟\n\nالجواب: لا، هذا بواسطة المخلوقين يعني.\n\nالطالب: ولم يقل المخلوقين.\n\nالجواب: التوسل بالأعمال الصالحات بالإيمان بالله، بأسمائه، وصفاته كما قال : وَلِلَّهِ الْأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180]... التوسل بالله، وأسمائه، وصفاته.\n\nالثاني: التوسل بالأعمال الصالحات، بالتقوى، والإيمان، وحب الله، ورسوله، ونحو ذلك.\n\nوالثالث: بدعاء الحي، وشفاعته.. التوسل بدعائه لك بأنه يغفر لك مثل ما كان يدعو الصحابة في حياته ﷺ ويشفع لهم أن يهديهم، ويشفي مريضهم، ونحو ذلك.","link":"https://binbaz.org.sa/fatwas/2920/التوسل-المشروع-والممنوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1368.mp3","categories":["التوسل والشفاعة","القرآن وعلومه"]},{"id":7339,"question":"هل قول المسلم: اللهم إني أسألك بجاه فلان، أو أسألك بفلان، أو بأعمال فلان، هل هذا يبطل التوحيد؟","title":"أنواع التوسل","answer":"الجواب: هذا يسمى \"توسل\" والتوسل أقسام: توسل شرعي، وهو التوسل إلى الله بطاعته، واتباع شريعته، وهذا هو الدين كله، الدين هو التوسل إلى الله بطاعته وتوحيده، والإخلاص له في دخول الجنة، والنجاة من النار، فتوحيد الله، وطاعة أوامره، وترك نواهيه، والوسيلة إلى جنته، وكرامته. والنوع الثاني: توسل بأسمائه وصفاته وأعمالك الصالحة في دعواتك، وهذا جائز أيضًًا، اللهم إني أسألك بأسمائك، وصفاتك أن تغفر لي، اللهم إني أسألك بإيماني بك، وبمحبتي لك ولنبيك، اللهم إني أسألك بأعمالي الصالحة، بطاعتي لك، واتباعي لشريعتك، وأدائي الأمانة، وبري الوالدين، وعفتي عما حرمت علي يا ربي، أسألك أن تغفر لي، هذا توسل بأسماء الله وصفاته وبأعمالك الطيبة، كل هذا توسل شرعي طيب مأمور به. والتوسل الثالث: التوسل بدعاء أخيك يدعو لك، يا فلان ادع الله لي، اللهم إني أسألك أن تقبل دعاءه لي، وما أشبه ذلك، كما كان النبي ﷺ يدعو لأصحابه، وهو توسل بدعائه، وكما دعا للأعمى حتى شفاه الله، هو توسل بدعاء الحي إذا دعا لك، واستغفر لك تقول: اللهم تقبل منه، هذا كله جائز، وكله شرعي. وهناك توسل باطل وتوسل شركي وهو نوعان: نوع معناه الشرك الأكبر، وهو توسل إلى الله بعبادة الأنبياء والأولياء والكواكب ونحو ذلك، كما قال الكفار: مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى [الزمر:3]، هَؤُلَاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ [يونس:18] هذا شرك أكبر أن يتوسل بالأنبياء والصالحين يدعوهم مع الله، يستغيث بهم، ينذر لهم، يتقرب إليهم بالسجود بالذبائح بطلب المدد، هذا شرك أكبر، ويسميه بعض المشركين توسلًا، وهكذا كونه يتوسل بالكواكب بالنجوم بالشمس بالقمر بالأصنام يدعوها، يستغيث بها، يطلبها المدد، يذبح لها، ينذر لها، هذا توسل شركي، شرك أكبر. أما الذي سألت عليه أيها السائل هو نوع ثاني، توسل محرم ممنوع، وهو أن تقول: اللهم إني أسألك بجاه نبيك، أو بجاه الأنبياء، أو بحق الأنبياء، أو بحق الوالدين، أو بحق فلان، أو بجاه فلان، هذا بدعي لا يجوز، وليس بشرك، لكنه من وسائل الشرك. والصحيح عند جمهور أهل العلم منعه، وأنه لا يجوز التوسل به؛ لأن الله ما شرع لنا التوسل بحق فلان، ولا بجاه فلان، ولا بذات فلان، ولكنه يتوسل بأسماء الله وصفاته وبأعمالنا الصالحة، كما قال : وَلِلَّهِ الْأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180]، وقال في الحديث الصحيح: من قال: اللهم إني أسألك بأني أشهد أنك أنت الله لا إله إلا الله، الواحد الصمد، الذي لم يلد ولم يولد لما سمع النبي رجلًا يدعو بهذا الدعاء قال: لقد سأل الله باسمه الذي إذا دعي به أجاب، وإذا سئل به أعطى. كذلك حديث الثلاثة الذين دخلوا في الغار وانطبقت عليهم الصخرة، فتوسلوا إلى الله أحدهم ببر والديه، والثاني توسل إلى الله بعفته عن الزنا، والثالث توسل إلى الله بأدائه الأمانة، فرج الله عنهم، فالتوسل بالإيمان والتقوى والعمل الصالح بأسماء الله وصفاته هذا هو المشروع، أو بدعاء أخيك لك إذا دعا لك هذا هو المشروع، أما التوسل بجاه فلان أو بحياة فلان أو بذات فلان أو بحق فلان هذا غير مشروع، بل هو بدعة، ولا يجوز عند أهل العلم، عند عامة أهل العلم وجمهور أهل العلم لا يجوز؛ لأنه توسل غير مشروع ما شرعه الله لنا.","link":"https://binbaz.org.sa/fatwas/3404/انواع-التوسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1717.mp3","categories":["التوسل والشفاعة"]},{"id":8558,"question":"له سؤال ثانٍ في هذه الرسالة يقول: للنبي ﷺ يوم القيامة ثلاث شفاعات فلمن تجوز الشفاعة الأولى والثانية والثالثة؟","title":"أنواع شفاعات النبي صلى الله عليه وسلم يوم القيامة","answer":"الجواب: له ﷺ ثلاث شفاعات خاصة به عليه الصلاة والسلام، إحداها الشفاعة العظمى في أهل الموقف يوم القيامة، فيشفع لهم حتى يقضى بينهم، وهذا هو المقام المحمود الذي قال فيه سبحانه: عَسَى أَنْ يَبْعَثَكَ رَبُّكَ مَقَامًا مَحْمُودًا [الإسراء:79].\nفهذا المقام المحمود الذي يبعثه الله يوم القيامة، وهو أنه يشفع في أهل الموقف عليه الصلاة والسلام، .. يشفع إلى الله أن يقضي بينهم في هذا الموقف العظيم حتى ينصرف كل إلى ما كتب الله له.\nالشفاعة الثانية: الشفاعة في أهل الجنة حتى يدخلوا الجنة، فإنهم لا يدخلونها إلا بشفاعته عليه الصلاة والسلام، فيشفع إلى ربه فيؤذن لهم في دخول الجنة.\nالشفاعة الثالثة: خاصة بعمه أبي طالب ، يشفع في عمه أبي طالب أن يخفف عنه، قال ﷺ: إنه وجده في غمرات النار، فشفع له حتى صار في ضحضاح من النار فالرسول ﷺ شفع لعمه أبي طالب فقط في التخفيف لا في الخروج؛ لأنه كافر مات كافراً، هذا الذي عليه أهل العلم والتحقيق، أنه مات كافراً ، أراده النبي ﷺ عند موته أن يقول: لا إله إلا الله، فأبى، وقال: هو على ملة عبد المطلب ، نعوذ بالله، فمات على الكفر بالله.\nفالرسول ﷺ شفع له بأن يكون في ضحضاح من النار، بسبب ما حصل من نصره للنبي ﷺ وتعبه وحمايته له عليه الصلاة والسلام، حرص ﷺ أن يسلم ولكن لم يقدر له الإسلام، فصار هذا من الآيات الدالة على أنه ﷺ لا يملك هداية أحد، الهداية بيد الله ، هو الذي يهدي من يشاء، ولهذا لما مات عمه أبو طالب على الكفر أنزل الله في حقه: إِنَّكَ لا تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [القصص:56] وقال سبحانه: لَيْسَ عَلَيْكَ هُدَاهُمْ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [البقرة:272] .. لهذا شفع فيه أن يكون في ضحضاح من النار يغلي منه دماغه نسأل الله العافية، فقد قال ﷺ: أهون الناس عذاباً يوم القيامة أبو طالب ؛ فإنه في ضحضاح من النار يغلي منه دماغه أو كما قال عليه الصلاة والسلام، وفي لفظ آخر يقول ﷺ: إن أهون أهل النار عذاباً يوم القيامة من يكون له نعلان من نار يغلي منهما دماغه، فهو يرى أنه أشد الناس عذاباً وهو أهونهم عذاباً نسأل الله العافية. نعم.\nالمقدم: جزاكم الله خير، هذه ثلاث شفاعات التي تفضلتم ببيانها خاصة به عليه الصلاة والسلام، معنى هذا أن هناك شفاعات أخرى؟\nالشيخ: نعم، في شفاعات أخرى، في شفاعة فيمن دخل النار وأن لا يدخلها، ... أن يخرج منها ومن لم يدخلها أن لا يدخلها من العصاة، فإن العصاة قسمان: قسم يعفى عنه قبل دخول النار بالشفاعة أو برحمة الله ، وعفوه جل وعلا، وقسم يدخلون النار بمعاصيهم وسيئاتهم ثم بعدما يمضي عليهم ما شاء الله في النار يخرجون منها بشفاعة الشفعاء أو برحمة الرب سبحانه المجردة من دون شفاعة أحد؛ لأنه كتب جل وعلا أنه لا يخلد فيها إلا الكفرة، النار لا يخلد فيها إلا الكفار، أما العصاة فإنهم يمكثون فيها ما شاء الله ثم يخرجون، هذا هو الذي عليه أهل الحق، أهل السنة والجماعة ، أن العصاة لا يخلدون في النار، بل يمكثون فيها ما شاء الله ثم يخرجهم الله من النار إلى نهر يقال له: نهر الحياة ، فينبتون فيه كما تنبت الحبة في حميل السيل، وهؤلاء الذين يخرجون من النار أقسام:\nمنهم من يخرج بشفاعة النبي صلى الله عليه وسلم، وهم أقسام، ومنهم من يخرج بشفاعة غيره من الأنبياء، ومنهم من يخرج بشفاعة الملائكة، ومنهم من يخرج بشفاعة المؤمنين والأفراط، ومنهم من يبقى في النار حتى يخرجه الله برحمته جل وعلا من دون شفاعة أحد، فإذا شفع الشفعاء وانتهى أمرهم يخرج الله من النار من كان فيها من بقية أهل التوحيد، الذين ماتوا على بعض السيئات والمعاصي، فيخرجهم سبحانه من النار فضلاً منه ورحمة سبحانه وتعالى.\nالمقدم: جزاكم الله خيراً، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/6637/انواع-شفاعات-النبي-صلى-الله-عليه-وسلم-يوم-القيامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_206/20610.mp3","categories":["التفسير","التوسل والشفاعة"]},{"id":8796,"question":"السؤال الثاني في رسالة الجماعة من الأردن، يقولون فيه: لنا إمام مسجد يقول: إنه يجوز للإنسان أن يسأل الله ببركة فلان: اغفر لي يا رب ببركة فلان أي: أحد الصالحين مثلاً، فهل هذا نوع من الشرك؟ وهل تجوز الصلاة خلفه؟ في نفس الوقت لا يصرح بها شفهياً إلا إذا سألناه، وهذا الإمام يكتب الحجاب والبخورات للناس لطرق علاج، هل نصلي خلفه أم لا أفيدونا أفادكم الله؟","title":"حكم الصلاة خلف من يتوسل بجاه أو بركة فلان","answer":"الجواب: هذا ليس من الشرك ولكنه من وسائل الشرك، التوسل ببركة فلان، أو بحق فلان، أو جاه فلان، أو نأتي فلان هذا من وسائل الشرك وليس من الشرك بل هو بدعة عند جمهور أهل العلم؛ لأن التوسل عبادة لابد لها من توقيف، لابد لها من بيان من الرسول ﷺ أو من الله ، والله سبحانه بين لنا وهكذا رسوله ﷺ بينا وسائل العبادة، وأن المشروع أن يتوسل إلى الله في دعائنا إياه بأسمائه، كما قال سبحانه: وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180]، وهكذا صفاته سبحانه وتعالى، وهكذا التوسل بالتوحيد: اللهم إني أسألك بأني أشهد أنك أنت الله لا إله إلا أنت، كما جاء في الحديث، وهكذا التوسل بالأعمال الصالحات، فيتوسل المؤمن بإيمانه بالله ورسوله، بمحبته لله ورسوله، ببره لوالديه، بأدائه الأمانة، بعفته عن الفواحش، بالمحافظة على الصلوات إلى غير ذلك.\nوفي هذا الباب قصة أهل الغار، وهو الحديث الذي رواه الشيخان البخاري ومسلم في الصحيحين عن ابن عمر رضي الله تعالى عنهما: أن ثلاثةً من الناس ممن كان قبلنا آواهم المبيت -وفي رواية: المطر- إلى غار فدخلوا فيه، فانحدرت عليهم صخرة سدت عليهم الباب، يقول النبي ﷺ إنهم فيما بينهم قالوا: لن ينجيكم من هذا الأمر إلا أن تسألوا الله بصالح أعمالكم، فقام أحدهم فسأل ربه ببره لوالديه، فانفرجت الصخرة بعض الشيء، وقام الثاني فسأل الله بعفته عن الفاحشة -عن الزنا- فانفرجت الصخرة بعض الشيء، وقام الثالث فتوسل إلى الله بأدائه الأمانة، فانفرجت الصخرة وخرجوا، فهذا دليل على أن التوسل بالأعمال الصالحات وسيلة شرعية، وهكذا التوسل بأسماء الله وصفاته، وهكذا التوسل بتوحيده والإخلاص له أما التوسل بجاه فلان أو بركة فلان أو حق فلان هذا لا أصل له، ولا يجوز بل هو من البدع، ولكن ليس من الشرك، والصلاة خلف الإمام الذي يقول هذا صحيحة، لكن ينبغي أن يعلم ويوجه إلى الخير، فإن عرف الحق وامتثل وتاب إلى الله من ذلك، وإلا فالواجب أن يبدل بغيره، الواجب على المسئولين أن يلتمسوا إماماً أصلح منه للمسجد، حتى لا يضر الناس، وهكذا إذا كان يتعاطى كتابة الحجب وهي التمائم هذا أيضاً منكر، والرسول ﷺ أمر بقطع التمائم، وقال: من تعلق تميمة فلا أتم الله له، ومن تعلق ودعة فلا ودع الله له، وأخبر أنها شرك، فلا يجوز كتابة التمائم، لا من العظام ولا من الخرز ولا من الطلاسم ولا من غير ذلك، واختلف العلماء فيما إذا كانت التمائم من القرآن على قولين: أحدهما: الجواز، والثاني: المنع، والصواب: المنع، أنه لا يجوز اتخاذ التمائم والحجب حتى ولو من القرآن في أصح قولي العلماء؛ لأن الرسول ﷺ نهى عن التمائم وأطلق وعمم، فلا يجوز استثناء شيء من ذلك؛ ولأن تعليق التمائم من القرآن وسيلة إلى تعليق غيرها، فينفتح الباب ويقع الشرك، وسد الذرائع أمر معلوم من الشريعة وأصل من أصولها؛ ولأن تعليقها قد يفضي إلى امتهان الآيات القرآنية فوجب منع ذلك.\nوأما البخور فشيء آخر، البخور قد يعالج بعض الأمراض بالبخور، ولكن بعض من يدعي الطب قد يتظاهر بأشياء وعنده أشياء أخرى، قد يتظاهر بالتمائم أو بالبخور وهو يتعاطى خدمة الجن وسؤال الجن، ودعوى علم الغيب بواسطة الجن، ومثل هذا خطره عظيم، فالواجب أن ينكر على هذا، وأن يوجه إلى الخير، وأن يعلم حتى يستفيد، وحتى ينتبه لهذا الخطر، فإن استقام وتاب إلى الله وشرع الطريق السوي وإلا فالواجب إبداله بغيره من أئمة المسلمين الذين عندهم العناية بأمر الله، وعندهم صلاح العقيدة وسلامة الدين، والله المستعان، ولا حول ولا قوة إلا بالله. نعم.","link":"https://binbaz.org.sa/fatwas/6948/حكم-الصلاة-خلف-من-يتوسل-بجاه-او-بركة-فلان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_221/22101.mp3","categories":["التوسل والشفاعة","صلاة الجماعة"]},{"id":9346,"question":"أخيراً يقول الأخ آدم عبد الله أبكر من تشاد، هل التوسل يجوز بالجاه وبالبركة وبالحرمة، كأن يقول الإنسان: اللهم افعل لي كذا بجاه الشيخ فلان، أو ببركة الشيخ فلان، أو بحرمة محمد ﷺ ونحو ذلك أفيدونا أفادكم الله؟","title":"حكم التوسل بجاه الأنبياء والصالحين","answer":"الجواب: التوسل بالجاه والبركة والحرمة والحق، ليس بجائز عند جمهور أهل العلم؛ لأن التوسلات توقيفية، لا يجوز منها إلا ما أجازه الشرع، ولم يرد في الشرع ما يدل على هذه التوسلات، فلا يقول الإنسان: اللهم اغفر لي بحق فلان، بحق محمد أو بحق الصالحين، أو بحق الأنبياء أو بجاه الأنبياء أو بحرمة الأنبياء، أو بركة الأنبياء أو بحق الصالحين أو بركة الصالحين أو بركة علي أو بركة الصديق ، أو بركة عمر ، أو حق الصحابة أو حق فلان وفلان كل هذا لا يحوز، هذا خلاف المشروع وهو بدعة وليس بشرك لكنه بدعة، لم يرد في الأسئلة التي دعا بها النبي صلى الله عليه وسلم، ودعا بها أصحابه ، وإنما يتوسل بما شرعه الله من أسماء الله سبحانه وصفاته، ومن توحيده، والإخلاص له والأعمال الصالحات، هذه الوسائل قال الله تعالى: وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180]، فتقول: اللهم اغفر لي برحمتك إنك أنت الغفور الرحيم، اللهم ارحمني يا أرحم الراحمين، اللهم أحسن إلي، اللهم أدخلنا الجنة برحمتك وفضلك وإحسانك، اللهم أنجني من النار، واعف عني يا رحمان يا رحيم يا عفو يا كريم وما أشبه ذلك، أو بالتوحيد والإخلاص لله، تقول: اللهم اغفر لي، لأني أشهد أنك أنت الله لا إله إلا أنت، لأنك الواحد الأحد مستحق العبادة، أو تقول: اللهم أني أسألك بأني أشهد أنك أنت الله لا إله إلا أنت كما جاء في الحديث الشريف بهذا السؤال فلا بأس بهذا، هذا وسيلة شرعية، أو بأعمالك الطيبة، تقول: اللهم اغفر لي بإيماني بك ومحبتي لك، أو بإيماني بنبيك ومحبتي له عليه الصلاة والسلام، اللهم ارحمني بطاعتي لك واتباعي لشريعتك، اللهم ارحمني ببر والدي، اللهم ارحمني بعفتي عن الفواحش، اللهم ارحمني بأداء الأمانة، ونصحي لله ولعباده وما أشبه ذلك، ومن هذا الباب ما ثبت في الصحيحين عن ابن عمر رضي الله تعالى عنهما: عن النبي ﷺ: أن ثلاثة آواهم المبيت إلى غار -وفي رواية: آواهم المطر إلى غار- في الجبل فدخلوا فيه، فانحدرت عليهم صخرة من أعلى الجبل فسدت الغار عليهم، وكانت صخرة عظيمة لم يستطيعوا دفعها، فقالوا فيما بينهم: إنه لن ينجيكم من هذه الصخرة إلا أن تدعوا الله بصالح أعمالكم، فدعوا الله سبحانه وتعالى فقال أحدهم: اللهم إنه كان لي أبوان شيخان كبيران، وكنت لا أغبق قبلهما أهلاً ولا مالاً، والغبوق اللبن الذي يسقاه يشربه الناس بعد العشاء وكان هذا من عادات العرب، سقي الضيوف والأهل اللبن في الليل، يقول: كنت لا أغبق قبلهما أهلاً ولا مالاً، وإنه نأى بي طلب الشجر ذات ليلة فلم أرح عليهما إلا في آخر الليل يعني إلا متأخراً، فوجدهما نائمين، فوقف والقدح على يديه ينتظر استيقاظهما فلم يستيقظا حتى برق الفجر، قال: اللهم إن كنت تعلم أني فعلت هذا ابتغاء وجهك فافرج عنا ما نحن فيه، فانفرجت الصخرة بعض الشيء، لكنهم لا يستيطعون أن يخرجوا، وقال الثاني: اللهم إني كانت لي ابنة عم أحبها كأشد ما يحب الرجال النساء، وإني راودتها على نفسها فأبت علي، ثم إنها ألمت بها سنة -يعني: حاجة- فجاءت إلي تطلب الرفد، فقلت لها: إلا أن تمكني من نفسك، فاتفق معها على مائة وعشرين دينار -جنيه- فمكنته من نفسها فلما جلس بين رجليها قالت له: اتق الله ولا تفض الخاتم إلا بحقه، فقام خائفاً من الله وترك الذهب وترك الفاحشة، ثم قال: اللهم إن كنت تعلم أني فعلت هذا ابتغاء وجهك فافرج عنا ما نحن فيه، فانفرجت الصخرة زيادة لكنهم لا يستيطعون الخروج، ثم قال الثالث: اللهم إنه كان لي أجراء فأعطيت كل أجير حقه إلا واحداً ترك أجره فربيته له، فنميته له حتى صار منه إبل وبقر وغنم ورقيق، ثم جاء يطلب أجره فقلت له: كل ما ترى من أجرك، فقال: اتق الله ولا تستهزئ بي، قلت: إني لا أستهزئ بك، كله من أجرك فاستاقه كله، اللهم إن كنت تعلم أني فعلت هذا ابتغاء وجهك فافرج عنا ما نحن فيه، فانفرجت الصخرة وخرجوا بأسباب هذه الدعوات وهذه الأعمال الصالحات.\nفالدعاء بهذا وأشباهه دعاء طيب لا بأس، ووسيلة صالحة، أما الدعاء بحق فلان، أو جاه فلان، أو بركة فلان، أو حرمة فلان، فهذا لا أصل له، ولم تأت به السنة، فالواجب تركه وليس من الشرك لكنه من البدع، فالواجب تركه، هذا هو الصواب الذي عليه جمهور أهل العلم، والله المستعان. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7511/حكم-التوسل-بجاه-الانبياء-والصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_238/23807.mp3","categories":["التفسير","التوسل والشفاعة"]},{"id":9693,"question":"السؤال الثاني في رسالتهم: ما حكم الدين في زيارة القبور والتوسل بالأضرحة وأخذ خروف وأموال للتوسل بها كزيارة السيد البدوي والحسين والسيدة زينب أفيدونا أفادكم الله؟","title":"حكم زيارة القبور والأضرحة والتوسل بها","answer":"الجواب: زيارة القبور نوعان:\nأحدهما: سنة ومشروع ومطلوب، وهو أن يزورها للدعاء لهم والترحم عليهم وذكر الموت وذكر الآخرة هذا سنة، لقول النبي ﷺ: زوروا القبور فإنها تذكركم الآخرة وكان النبي يزورها ﷺ، وهذا للرجال خاصة لا للنساء.\nالنوع الثاني: أن يزورها لدعاء أهلها والاستغاثة بهم أو للذبح لهم أو يولم بالذبائح هذا منكر وشرك أكبر نسأل الله العافية، ويلتحق بذلك أن يزورها للدعاء عندها والصلاة عندها والقراءة عندها هذا بدعة غير مشروع، فصارت في الحقيقة ثلاثة أنواع:\nالنوع الأول مشروع: وهو أن يزورها للذكرى والدعاء وتذكر الآخرة، هذه سنة.\nوالثاني: أن يزورها للقراءة عندها أو الصلاة عندها أو الذبح عندها لله هذه بدعة.\nالثالث: أن يزورها ليذبح للميت ويتقرب إليه بالذبائح، أو ليدعوه من دون الله ليطلبه المدد أو الغوث والنصر هذا شرك أكبر نسأل الله العافية فيجب الحذر من هذه الزيارات الخبيثة. نعم.","link":"https://binbaz.org.sa/fatwas/7839/حكم-زيارة-القبور-والاضرحة-والتوسل-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19421.mp3","categories":["زيارة القبور","التوسل والشفاعة"]},{"id":10980,"question":"هذا السائل من جدة رمز لاسمه بـ (ن. ع) يقول: هل يجوز للإنسان يا سماحة الشيخ! أن يدعو في دعائه بقول: اللهم بحق محمد عندك؛ لأنني سمعت بعض الناس يقولون: بأن آدم  عندما أذنب دعا وقال لربه: بجاه محمد عندك اغفر لي، وجزاكم الله خيرًا يا سماحة الشيخ؟","title":"التوسل بالجاه غير مشروع","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فهذا التوسل لا يجوز؛ لأن الوسائل توقيفية عبادة لا يجوز منها إلا ما أجازه الشرع، والله يقول سبحانه: وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180] فلا يدعى إلا بأسمائه وصفاته والإيمان به، وتوحيده -جل وعلا- ولا يدعى بما يراه الإنسان من التوسلات، ولا بجاه فلان، ولا بحق فلان، ولا بحق محمد، ولا بجاه محمد، ولا بجاه الأنبياء، ولا بحق الأنبياء، كل هذا لا يجوز، هذا هو الصواب؛ لأن التوسل عبادة والعبادة توقيفية، لا تثبت بالرأي المجرد، والاختيار لا، لا بد من الدليل على ذلك، قال الله -جل وعلا-: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21] أنكر عليهم : وقال : ثُمَّ جَعَلْنَاكَ عَلَى شَرِيعَةٍ مِنَ الأَمْرِِ فَاتَّبِعْهَا [الجاثية:18]. وقال النبي ﷺ: من عمل عملًا ليس عليه أمرنا فهو رد وقال ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد والشريعة جاءت بالتوسل بأسماء الله وصفاته، والإيمان به وتوحيده. اللهم إني أسألك بأني أؤمن بك، بتوحيدي لك، بإخلاصي عبادتك إلى غير ذلك، بأسمائك وصفاتك، بصلاتي بصومي بحجي ببري لوالدي إلى غير ذلك. فالتوسل إلى الله بأسمائه وصفاته والإيمان به، أو بالأعمال الصالحات كل هذا لا بأس به وسيلة شرعية. ومن هذا حديث الغار، أصحاب الغار ثلاثة كانوا في سفر فيمن قبلنا أخبر عنهم النبي ﷺ فآواهم المبيت إلى غار، وفي رواية: المطر، فلما دخلوا الغار انحدرت عليهم صخرة فسدت عليهم الغار، وكانت عظيمة لم يستطيعوا دفعها. فقالوا -فيما بينهم-: إنه لن ينجيكم من هذه الصخرة إلا أن تدعوا الله بصالح أعمالكم، فتوسلوا إلى الله بصالح أعمالهم؛ ففرج الله عنهم الصخرة، الأول: من توسل ببره لوالديه، والثاني: توسل بعفته عن الزنا، والثالث: توسل بأدائه الأمانة، ففرج الله عنهم. هذه هي الوسيلة الشرعية، أسماء الله وصفاته وتوحيده والإيمان به والأعمال الصالحات، أما التوسل بجاه النبي، أو بحق النبي، أو بجاه الأنبياء، أو بحق الأنبياء، أو بجاه المؤمنين، كل هذا غير مشروع، بل هو بدعة. وأما حديث أن آدم توسل بمحمد ﷺ أو بحق محمد ﷺ هذا حديث موضوع غير صحيح، بل نبه العلماء على أنه موضوع لا صحة له، ولا أصل له، ولا أساس له. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9158/التوسل-بالجاه-غير-مشروع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_287/28701.mp3","categories":["التوسل والشفاعة"]},{"id":11729,"question":"تقول: ما حكم التوسل بجاه الله ؟","title":"حكم التوسل بجاه الله وسائر صفاته تعالى","answer":"الجواب:  بالتوسل بجاه الله إلى الله : أسألك بجاهك العظيم، بعلمك العظيم، برحمتك، بإحسانك، بجبروتك، بعزتك، كله طيب ما فيه بأس، جاهه عظمته  فإذا سأل الله بذلك؛ فلا بأس، اللهم إني أسألك بجاهك العظيم، بعلمك العظيم، بقدرتك، بعزتك أن تغفر لي، أن ترحمني. أما سؤال الناس بالله؛ تركه أولى، لا يسأل الناس بالله، ولا بجاه الله، لا يقول: أسألك بالله، أو بجاه الله أن تفعل كذا؛ ترك هذا أولى وأحوط. المقدم: جزاكم الله خيرًا، هل كلمة غالب صفة من صفات الله؟ الشيخ: صفة من صفاته  نعم.","link":"https://binbaz.org.sa/fatwas/9912/حكم-التوسل-بجاه-الله-وساىر-صفاته-تعالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_421/42110.mp3","categories":["التوسل والشفاعة"]},{"id":12573,"question":"حدثونا عن شفاعة النبي ﷺ إذ أني سمعت عن هذا بعض الشيء، وأريد أن أستدرك كثيرًا مما فاتني حول هذا الموضوع، جزاكم الله خيرًا.","title":"شفاعات النبي صلى الله عليه وسلم الخاصة والعامة","answer":"الجواب:  النبي ﷺ له شفاعات: منها: شيء يختص به، ومنها: شيء يشترك معه الناس فيها، فأما الشفاعة التي تختص به؛ فهي الشفاعة العظمى في أهل الموقف، يشفع بينهم، يسجد بين يدي ربه، ويحمده بمحامد عظيمة، ثم يأذن الله له في الشفاعة، فيشفع في أهل الموقف؛ حتى يقضى بينهم. وهذه من خصائصه -عليه الصلاة والسلام- وهذه هي المقام المحمود الذي ذكر الله في قوله -جل وعلا- في سورة بني إسرائيل: عَسَى أَنْ يَبْعَثَكَ رَبُّكَ مَقَامًا مَحْمُودًا [الإسراء:79] وهذا المقام هو مقام الشفاعة، يحمده فيه الأولون والآخرون -عليه الصلاة والسلام- فإنه تتوجه إليه الخلائق في يوم القيامة، المؤمنون يتوجهون إليه بعدما يتوجهون إلى آدم ونوح وإبراهيم وموسى وعيسى، فكلهم حيرة، كلهم يعتذرون، يأتون آدم ويعتذر، ونوح يعتذر، وإبراهيم وموسى وعيسى كلهم يعتذرون، ثم يقول لهم عيسى: اذهبوا إلى عبد قد غفر الله له ما تقدم من ذنبه وما تأخر يعني: محمد -عليه الصلاة والسلام- فيتوجهون إليه، فإذا طلبوا منه؛ تقدم -عليه الصلاة والسلام- إلى ربه، وسجد بين يدي العرش، وحمده سبحانه بمحامد عظيمة يفتحها الله عليه، ثم يقال له: يا محمد ارفع رأسك، وقل يسمع، وسل تعط، واشفع تشفع فيشفع عند ذلك بعد إذن الله  لأنه يقول -جل وعلا-: مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ [البقرة:255] فلا أحد يشفع عنده إلا بإذنه . وهناك شفاعة أخرى خاصة به -عليه الصلاة والسلام- وهي الشفاعة في أهل الجنة أن يدخلوا الجنة؛ فإنهم ما يدخلون، ولا تفتح لهم إلا بشفاعته -عليه الصلاة والسلام- فهذه خاصة به أيضًا، عليه الصلاة والسلام. وهناك شفاعة ثالثة خاصة به، وبـأبي طالب عمه، وهو أنه شفع له حتى صار في ضحضاح من النار، وهو مات على الكفر بالله، وصار في غمرات من نار، فشفع له ﷺ أن يكون في ضحضاح من النار؛ بسبب نصره إياه؛ لأنه نصره، وحماه لما تعدى عليه قومه، فشفع له ﷺ أن يكون في ضحضاح من النار، وهذه شفاعة خاصة بـأبي طالب مستثناة من قوله -جل وعلا-: فَمَا تَنْفَعُهُمْ شَفَاعَةُُ الشَّافِعِينَ [المدثر:48] إلا في هذه الخصلة مع أبي طالب خاصة، وأبو طالب مخلد في النار مع الكفرة، لكنه في ضحضاح من النار يغلي منه دماغه، نسأل الله العافية. وأهون الناس عذابًا أبو طالب وأشباهه، قال النبي ﷺ: إن أهون الناس عذابًا يوم القيامة من له نعلان من نار يغلي منهما دماغه -نسأل الله السلامة- في رواية: من يوضع على قدميه جمرتان من نار يغلي منهما دماغه فهو يرى أنه أشد الناس عذابًا، وهو أهونهم عذابًا، وأبو طالب من هذا الصنف، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10779/شفاعات-النبي-صلى-الله-عليه-وسلم-الخاصة-والعامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_457/45705.mp3","categories":["التوسل والشفاعة"]},{"id":12907,"question":"رجل يقول أحيانًا في دعواته: اللهم بشرف الرسول اشفني، ويسر أموري بجاه محمد ﷺ فأخبرته أن هذا لا يجوز، وأن الدعاء يكون لله  بعظمته ومقدرته وبجاهه، وإذا أردت أن تقول بدلًا من هذا فافعل، وقل: اللهم شفع في نبيك محمدًا ﷺ هل ما قلت للرجل صحيح -يا سماحة الشيخ- وما حكم الدعاء بشرف وجاه الرسول الكريم ﷺ وماذا أفعل إذا كنت مخطئًا في قولي هذا؟ وجهوني، جزاكم الله خيرًا.","title":"حكم التوسل بجاه النبي وبيان التوسل المشروع","answer":"الجواب:  كلامك طيب، وأنت مصيب، أنت مصيب بما فعلت، فلا يشرع التوسل بشرف الرسول ﷺ، ولا بحق الرسول، ولا بجاهه، ولا بجاه فلان، ولا بحق الأنبياء، ولا شرف الأنبياء؛ لأن الله سبحانه ما شرع ذلك، إنما شرع لنا التوسل بأسمائه وصفاته، وبالأعمال الصالحات، هذه الوسيلة في الدعاء، قال الله تعالى: وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180] وشرع لنا التوسل بصفاته، كما أن تسأله وتقول: اللهم إني أسألك برحمتك، بجودك وكرمك أن تغفر لي، بعلمك الغيب، بقدرتك على الخلق أن تغفر لي، وأن ترحمني. أو تتوسل بأعمالك الصالحة، بتوبتك إليه، وإيمانك به سبحانه، وتوحيدك له، ومحبتك له، أو بطاعتك للرسول ﷺ ومحبتك للرسول ﷺ، أو بأدائك الصلاة لله وحده سبحانه، أو ما أشبه ذلك من الأعمال الصالحات. أما التوسل بجاه فلان، أو شرف فلان، أو حق فلان هذا لا يجوز على الصحيح الذي عليه جمهور أهل العلم. والأصل في هذا قوله سبحانه: وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180] وهكذا ما صح عن رسول الله ﷺ من تعليم الناس في التوسل إلى الله بصفاته، وأسمائه، وبالأعمال الصالحات. وقد وقع ثلاثة في غار، فسد عليهم الغار بصخرة عظيمة لم يستطيعوا دفعها، فقالوا فيما بينهم: إنه لا يخلصكم من هذه المصيبة إلا أن تدعوا الله بصالح أعمالكم، فدعوا الله، وسألوه بصالح أعمالهم؛ ففرج الله عنهم، وأزاح عنهم الصخرة. أحدهم: توسل ببره لوالديه. والثاني: توسل بعفته عن الزنا. والثالث: توسل بأدائه الأمانة، ففرج الله عنهم  فهذه هي الوسيلة الشرعية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11122/حكم-التوسل-بجاه-النبي-وبيان-التوسل-المشروع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_468/46809.mp3","categories":["التوسل والشفاعة"]},{"id":13417,"question":"هذا سائل مصري يقول: يقول أحد الأشخاص: الذي يتوجه بالدعاء إلى الله عند قبور الصالحين فهذا هو التوسل بالأولياء والصالحين، والتوسل جائز شرعًا، وهو بطلب من الله متوسلًا إليه بهذا الولي؛ عسى أن يكون هذا الدعاء، أو دعاء السائل مقبولًا، وليس في ذلك ما يتنافى مع العقيدة، لا فرق في ذلك بين الحي والميت، والدليل على ذلك بأن الرسول ﷺ جاءه أعمى، فقال له: يا رسول الله! اطلب من الله أن يرد علي بصري، فقال له: اذهب فتوضأ، وصل لله ركعتين، ثم قل: اللهم إني أتوسل إليك بنبيك محمد، نبي الرحمة يا سيدي يا رسول الله، توسلنا بك إلى ربي ليرد علي بصري، فرد الله عليه بصره ويقول أيضًا بأنه يجوز الاستعانة بالأحياء والأموات؛ لأن السائل يسأل الله ببركة هذا الصالح من نبي، أو ولي، وليس طالبًا من ذات الشخص أن يفعل شيئًا، نرجو من سماحتكم الإفادة عن هذا الموضوع؟","title":"حكم التوسل والاستعانة بالأولياء والصالحين","answer":"الجواب: هذا سؤال جدير بالعناية، وفيه تفصيل: فالحي الحاضر لا بأس أن يسأل أن يشفع للسائل، كما كان الصحابة يسألون النبي ﷺ أن يشفع لهم، إذا أجدبوا أن يستغيث لهم، وكما سأله الأعمى، فأمره أن يسأل ربه، أن يقبل شفاعة نبيه ﷺ وأمره أن يتوضأ، ويسأل ربه، فهذا لا بأس به، سؤال الأحياء أن يشفعوا لك، تقول: يا أخي ادع الله لي، اسأل الله لي، اشفع لي أن الله يشفيني، اشفع لي أن الله يرزقني، أن الله يمنحني زوجة صالحة، ذرية طيبة، لا بأس، تقول لأخيك وهو يدعو ربه، يرفع يديه، ويدعو ربه، اللهم اشف فلانًا، اللهم يسر أمره، اللهم ارزقه الزوجة الصالحة، اللهم ارزقه الذرية الطيبة لا بأس، كما كان الصحابة يسألون النبي ﷺ، وكما كان الصحابة -أيضًا- فيما بينهم، كل هذا لا بأس به، والنبي ﷺ قال لهم: إنه يقدم عليكم رجل بر بأمه، يقال له: أويس القرني، كان برًا بأمه، فمن لقيه منكم؛ فليطلب منه أن يستغفر له، فهذا شيء لا بأس به. أما سؤال الأموات والاستغاثة بالأموات، والنذر للأموات فشرك أكبر، هذا عمل الجاهلية، عمل قريش في جاهليتها، وعمل غيرهم من الكفرة، سؤال الأموات، وأصحاب القبور، والاستغاثة بهم، والاستعانة بهم؛ هذا الشرك الأكبر، هذا عبادة غير الله التي قال فيها -جل وعلا-: وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] وقال فيها سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117]. ومن دعا الأنبياء، أو دعا نبينا ﷺ بعد الموت، أو استغاث بالصديق، أو بـعمر، أو بعثمان، أو بعلي، أو بغيرهم؛ فقد اتخذهم آلهة، جعلهم آلهة مع الله، قال الله -جل وعلا-: ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:13-14] سماه شركًا، وقال -جل وعلا-: وَمَنْ أَضَلُّ مِمَّنْ يَدْعُو مِنْ دُونِ اللَّهِ مَنْ لا يَسْتَجِيبُ لَهُ إِلَى يَوْمِ الْقِيَامَةِ وَهُمْ عَنْ دُعَائِهِمْ غَافِلُونَ ۝ وَإِذَا حُشِرَ النَّاسُ كَانُوا لَهُمْ أَعْدَاءً وَكَانُوا بِعِبَادَتِهِمْ كَافِرِينَ [الأحقاف:5-6] فأخبر سبحانه أنه لا أضل من هؤلاء؛ دعاة غير الله. فالمقصود: أن الواجب على المؤمن أن يحذر دعاء الأموات، أو الغائبين كالملائكة، أو الجن يدعوهم، يسأل جبرائيل، أو إسرافيل، أو جن البلاد الفلانية، أو جن الجبل الفلاني، هذا شرك أكبر، قال ... -جل وعلا-: وَيَوْمَ يَحْشُرُهُمْ جَمِيعًا ثُمَّ يَقُولُ لِلْمَلائِكَةِ أَهَؤُلاءِ إِيَّاكُمْ كَانُوا يَعْبُدُونَ ۝ قَالُوا سُبْحَانَكَ أَنْتَ وَلِيُّنَا مِنْ دُونِهِمْ بَلْ كَانُوا يَعْبُدُونَ الْجِنَّ أَكْثَرُهُمْ بِهِمْ مُؤْمِنُونَ [سبأ:40-41] وقال -جل وعلا- في سورة الجن: وَأَنَّهُ كَانَ رِجَالٌ مِنَ الإِنسِ يَعُوذُونَ بِرِجَالٍ مِنَ الْجِنِّ فَزَادُوهُمْ رَهَقًا [الجن:6]. فالواجب الحذر، فلا يسأل الأموات، ولا الغائبين من الملائكة، ولا غيرهم، ولا يسأل الأصنام، ولا الجمادات من الأشجار والأحجار، والنجوم لا، يسأل الله وحده، يسأل الله، يستعين بالله، يستغيث بالله، قال تعالى: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] وقال سبحانه: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60]، وقال جل وعلا: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5]، وقال سبحانه: وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ [البقرة:186] وقال سبحانه: قُلْ إِنَّ صَلاتِي وَنُسُكِي [الأنعام:162] يعني: ذبحي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ [الأنعام:162-163] وقال سبحانه: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:1-2]، وقال النبي ﷺ: إذا سألت؛ فاسأل الله، وإذا استعنت؛ فاستعن بالله وقال ﷺ: لعن الله من ذبح لغير الله. فهذه أمور عظيمة خطيرة، والجلوس عند القبور يدعو ربه عند القبور هذه وسيلة للشرك، كونه يجلس عندها يقرأ، أو يدعو هذه وسيلة ما يجوز من وسائل الشرك. أما إذا دعا المقبور، واستغاث به؛ هذا الشرك الأكبر، هذا الذنب الذي لا يغفر إلا بالتوبة، أما الحي الحاضر تقول له: ادع الله لي، أو يسأل منه أن يعينه على كذا لا بأس، إذا كان حي حاضر قادر لا بأس، مثلما كان الصحابة يسألون النبي ﷺ وهو حاضر أن يعينهم، وأن يواسيهم مما أعطاه الله من المال، وأن يدعو لهم لا بأس، ومثلما قال الله عن موسى في قصة موسى مع القبطي: فَاسْتَغَاثَهُ الَّذِي مِنْ شِيعَتِهِ عَلَى الَّذِي مِنْ عَدُوِّهِ [القصص:15] فأغاثه موسى، وقتل القبطي، لأن موسى حي حاضر يسمع الكلام. وهكذا في الحرب الإنسان مع إخوانه في الحرب في الجهاد يتعاونون في قتال الأعداء، هذا يعين بالسلاح، وهذا يعين بالسوط، وهذا يعين بالفرس، وهذا يعين بالدرق.. إلى غير ذلك. وهكذا في الدنيا يتعاونون في المزرعة، يعينه في مزرعته، يعينه في بيعه وشرائه، حي قادر حاضر، يتعاونون في المزرعة، في البيع والشراء، في بناء البيت لا بأس، حي قادر حاضر لا بأس.  أما ميت، أو غائب لا، لا يستعان به؛ شرك أكبر، والمشركون ما كانوا يعتقدون أنهم يخلقون، أو يرزقون لا، المشركون يعبدونهم؛ لأنهم بزعمهم يشفعون لهم، يقربونهم إلى الله زلفى، هذا زعمهم، ما كانوا يعتقدون فيهم أنهم يخلقون، أو يرزقون، قال الله -جل وعلا-: وَلَئِنْ سَأَلْتَهُمْ مَنْ خَلَقَهُمْ لَيَقُولُنَّ اللَّهُ [الزخرف:87] وقال سبحانه: قُلْ مَنْ يَرْزُقُكُمْ [يونس:31] يعني قل لهم يا محمد. مَنْ يَرْزُقُكُمْ مِنَ السَّمَاءِ وَالأَرْضِ أَمَّنْ يَمْلِكُ السَّمْعَ وَالأَبْصَارَ وَمَنْ يُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَيُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ وَمَنْ يُدَبِّرُ الأَمْرَ فَسَيَقُولُونَ اللَّهُ [يونس:31] يعترفون بهذا، وقال -جل وعلا-: وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لا يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَيَقُولُونَ هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ [يونس:18] ما قال ليقولون: هذا خالقونا أو رازقونا لا وَيَقُولُونَ هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ [يونس:18].  هم يعلمون أن الخلاق الرزاق هو الله -سبحانه- وإنما يعبدون الأصنام؛ لأنها تشفع لهم بزعمهم، وقد أبطلوا في هذا، وقال -جل وعلا-: وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى [الزمر:3] يعني يقولون: ما نعبدهم إلا ليقربونا إلى الله زلفى، قال الله -جل وعلا-: إِنَّ اللَّهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ إِنَّ اللَّهَ لا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّارٌ [الزمر:3] سماهم كذبة، وسماهم كفرة، كذبة ما يقربونهم إلى الله زلفى، وهم كفرة بهذا بدعائهم إياهم، وذبحهم لهم، ونذرهم لهم، هم كفرة بهذا، سواء كانوا أنبياء المعبودون، أو صالحين أو ملائكة، من عبدهم؛ كفر باستغاثته بهم، بنذره لهم، بذبحه لهم يقول: إنهم يقربونه إلى الله زلفى، إنهم يشفعون له، هذا دين المشركين، هذا دين عباد الأصنام، يزعمون أنها تقربهم إلى الله، وتشفع لهم، لا أنها تخلق وترزق. فالذي يأتي البدوي، أو الحسين، السيد الحسين، أو غيره، أو ... الشيخ عبدالقادر الجيلاني، أو يأتي غيرهم، يسألهم، ويستغيث بهم، هذا قد جعلهم آلهة مع الله، وهذا هو الشرك الأكبر، وهكذا إذا أتى قبر النبي ﷺ يدعوه، يستغيث به، هذا الشرك الأكبر. فالواجب الحذر، الواجب على السائل، وعلى غير السائل الحذر من هذه الشركيات، وعدم الالتفات إلى دعاة الشرك من علماء السوء، وقادة السوء، نسأل الله العافية، والسلامة. نعم. المقدم: شكر الله لكم سماحة الشيخ، وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/11711/حكم-التوسل-والاستعانة-بالاولياء-والصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_526/52610.mp3","categories":["التوسل والشفاعة"]},{"id":14166,"question":"المستمع (م. م) مصري مقيم في المملكة يسأل أيضًا كسؤاله السابق عن حكم من يصلي بالناس الجمعة ويقول في خطبته: اللهم ربنا عليك توكلنا وبنبيك إليك توسلنا، وما حكم هذا التوسل أفيدونا بارك الله فيكم؟","title":"حكم التوسل بالنبي وبيان التوسل المشروع","answer":"الجواب: هذا التوسل بدعة عند جمهور أهل العلم لكن الصلاة صحيحة، ولكن التوسل بدعة، التوسل بجاه نبينا أو بنبينا أو بحق نبينا أو بحق الأنبياء أو بحق الملائكة أو بذات الملائكة أو بحق فلان أو فلان ابن فلان أو بحق أبي أو ما أشبه ذلك كل هذا ليس من الشرع، الوسيلة تكون بأسماء الله وصفاته وبالأعمال الصالحات كما قال الله جل وعلا: وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180]، فيقول: اللهم إني أسألك بأسمائك الحسنى وصفاتك العلى أن ترحمنا و..... أن تسقينا الغيث إلى غير ذلك، أو اللهم إني أسألك بإيماني بك وطاعتي لك واتباعي لنبيك يتوسل بأعماله الطيبة.\nأما التوسل بجاه فلان أو بنبينا أو بجاه نبينا أو بحق نبينا أو بحق الأنبياء أو الملائكة هذا كله بدعة عند أهل السنة ليس عليه دليل.\nوقد ثبت في الحديث الصحيح أنه قال عليه الصلاة والسلام لما سمع رجلًا يقول: اللهم إني أسألك بأني أشهد أنك أنت الله لا إله إلا أنت الأحد الصمد الذي لم يلد ولم يولد ولم يكن له كفوًا أحد، قال ﷺ: لقد سأل الله باسمه الذي إذا سئل به أعطى وإذا دعي به أجاب، لأنه توسل بصفات الله سبحانه وأسمائه. وهكذا التوسل بالأعمال الصالحات كما ثبت في الصحيحين من حديث ابن عمر رضي الله عنهما أن ثلاثة آواهم المبيت والمطر إلى غار في البرية فدخلوا فيه ليبيتوا فيه ويتقوا المطر فانحدرت عليهم صخرة من الجبل فسدت عليهم فم الغار -بإذن الله - ليسن لعباده ويشرع لعباده ما فعله أهل الغار وليعلم الناس علاج الكروب بما شرعه الله، فلما انطبقت عليهم الصخرة أرادوا دفعها فلم يستطيعوا فقالوا فيما بينهم: إنه لن ينجيكم من هذا البلاء إلا أن تدعوا الله بصالح أعمالكم، فانفرجت الصخرة وخرجوا يمشون برحمة الله ، بأسباب هذه الوسيلة العظيمة على أعمال صالحة فعلوها لله فنفعتهم عند الحاجة توسلوا بها عند الحاجة فنفعتهم.\nفهذا يدل على أن التوسل بالأعمال الصالحة من أعظم الوسائل ولا سيما عند الحاجة والشدة وهو القائل جل وعلا: أَمَّنْ يُجِيبُ الْمُضطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ السُّوءَ [النمل:62] ، وهو القائل جل وعلا: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60] فهو سبحانه قدر هذه الصخرة ليتوسل هؤلاء وليعرفوا فضل أعمالهم وليعرف الناس أيضًا فضل أعمالهم، وليتوسلوا كتوسلهم إذا وقعت عليهم الشدائد، والنبي ﷺ قص علينا هذه القصة لنعلمها ونعمل بها ونستفيد منها، وهو حديث صحيح متفق على صحته عند البخاري ومسلم رحمة الله عليهما. والله ولي التوفيق.\nالمقدم: جزاكم الله خيرا ونفع بكم، إذًا نستخلص مما تفضلتم به أن التوسل بالنبي ﷺ غير جائز، إنما التوسل بالأعمال الصالحة هو المطلوب وهو الجائز؟\nالشيخ: نعم بالأسماء الحسنى أسماء الله وصفاته وبالإيمان والتوحيد وبالأعمال الصالحات كلها وسائل، أما بذات النبي ﷺ أو جاه النبي أو جاه الأنبياء أو الملائكة أو غيرهم ليس بوسيلة.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12607/حكم-التوسل-بالنبي-وبيان-التوسل-المشروع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_485/48509.mp3","categories":["التوسل والشفاعة"]},{"id":14474,"question":"ما حكم دراستنا على الشيخ الذي يستغيث بغير الله، ويتوسل بالصالحين، وإذا قام من مكانه قال: يا فلان؟","title":"حكم الدراسة على من يستغيث بغير الله ويتوسل بالصالحين","answer":"الجواب: مثل هذا لا يقرأ عليه، ولا ينقل عنه العلم لشركه، ولا يؤمن أن يشبه على الطلبة فيوافقوه على ما هو عليه من الباطل، بل الواجب أن ينصح ويبيّن له أغلاطه من أهل العلم، حتى ولو من الطلبة بالأسلوب الحسن، بالكلام الطيب، فالمؤمن لا يحقر نفسه عن بيان العلم، كان النبي ﷺ ذات يوم بين أصحابه فقال: حدثوني عن شجرة لا يسقط ورقها هي مثل المؤمن قال ابن عمر: فوقع الناس في شجر البوادي، ووقع في نفسي أنها النخلة فاستحييت؛ لأنه كان أصغر القوم، فقال النبي ﷺ: إنها النخلة قال عبدالله: فقلت لأبي عمر: إنه وقع في نفسي أنها النخلة فاستحييت، فقال عمر: «لأن تكون قلتها أحب إلي من كذا وكذا» فأرشده عمر  إلى أنه يقول العلم، يتبين يتكلم يتقدم بالعلم ولو كان صغيرًا. وكان عمر  يدني ابن عباس مع الكبار في المشورة؛ لما أظهر له من علمه، كان يدنيه معهم ويستشيره معهم لما أعطاه الله من العلم والفقه في الدين.\nفالطالب إذا عرف من أستاذه غلطًا فلا مانع، بل يجب أن ينبهه بالأسلوب الحسن، بالسؤال: ما حكم كذا؟ ما الدليل على كذا أيها الأستاذ؟ يا أبا فلان، يا شيخنا، يأتي بالعبارات المناسبة، أو يطلب من العلماء الآخرين أن يرشدوا هذا العالم لعله يقبل منهم، أو يجتمع هو والطلبة ويكونون جميعًا، ويأتون الشيخ في بيته ليس عند الناس، فيقولون له: إنا سمعنا منك كذا وكذا، وقد ظهر لنا أن هذا الشيء حكمه كذا وكذا، من الدليل الفلاني،.... الدليل الفلاني، فأحببنا أن نبحث معك الموضوع، من باب النصيحة، ومن باب التعاون على البر والتقوى، لعله يقبل منهم، ولعله يستفيد، ولا يضرهم ذلك لو تكلم عليهم أو احتقرهم أو زعل عليهم، لا يضرهم ذلك، هم عليهم أن يحاولوا النصيحة، وبذل المستطاع في إرشاده وتنبيهه، والله ولي التوفيق ، لَيْسَ عَلَيْكَ هُدَاهُمْ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ [البقرة:272]، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12985/حكم-الدراسة-على-من-يستغيث-بغير-الله-ويتوسل-بالصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_625/62511.mp3","categories":["نواقض الإسلام","التوسل والشفاعة"]},{"id":14484,"question":"السؤال الآخر: ما حكم الصلاة وراء رجل يستغيث بغير الله، ويتوسل بالصالحين؟","title":"حكم الصلاة خلف من يتوسل بالصالحين ويستغيث بغير الله","answer":"الجواب: الصلاة خلف المشرك لا تجوز، ولا يجوز أن يقتدى به؛ لأن من استغاث بغير الله يعتبر مشركًا، فلا يصلى خلفه سواءً استغاث بالنبي ﷺ، أو بـالبدوي أو بـالحسين ، أو بالشيخ عبدالقادر، أو بغيرهم من الناس، فالذي يستغيث بالأموات، ويسألهم الحاجات والمدد يعتبر مشركًا، عليه أن يتوب إلى الله، وأن يبادر بذلك، ومن تاب صادقًا تاب الله عليه؛ لكن لا يتخذ إمامًا ولا مؤذنًا، بل يجب أن يكون المؤذن من أهل التوحيد، وهكذا الإمام، وإذا وجد في المسجد إمام مشرك يجب أن يزال، يجب على ولاة الأمور أن يزيلوه، وأن يعينوا مكانه عالمًا موحدًا بعيدًا عن الشرك؛ لأن ذلك هو الواجب على أئمة الإسلام، وعلى حكام المسلمين ألا يقدموا في المساجد من هو مشرك بالله، فإن إمامته باطلة، وهكذا المؤذنون يجب أن يكونوا مسلمين؛ لأنهم يخبروا الناس بالأوقات، ويعتمد عليهم، فلا بد أن يكون المؤذن أمينًا مسلمًا موحدًا، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12982/حكم-الصلاة-خلف-من-يتوسل-بالصالحين-ويستغيث-بغير-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_625/62509.mp3","categories":["نواقض الإسلام","التوسل والشفاعة","نصائح وتوجيهات"]},{"id":14904,"question":"هذه أختنا السائلة أختكم في الله أم عادل، من المدينة المنورة، تقول: هل شفاعة الأطفال الصغار لوالديهم، سواء كانوا ذكورًا أو إناثًا، أم أن الشفاعة تخص الأطفال الذكور فقط؟","title":"هل شفاعة من يموت صغيرًا لآبائهم خاصة بالذكور؟","answer":"الجواب: الشفاعة تعم الجميع، الذكور والإناث، والحمد لله، يقول النبي ﷺ: من مات له ثلاثة أفراط لم يبلغوا الحنث، كن له حجابًا من النار قالوا: يا رسول الله، أو اثنين؟ قال: أو اثنين ولم يسألوه عن الواحد، ويقول ﷺ: من مات له صفيه من الدنيا فصبر واحتسب عوضه به الجنة أو كما قال -عليه الصلاة والسلام-. المقصود: أن الإنسان إذا أصاب قريبه الذي هو صفيه من الدنيا قريب، أو صديق واحتسب؛ عوضه به الجنة، هذا معنى الحديث عن النبي ﷺ، في اللفظ الآخر: من أخذت صفيه من الدنيا فاحتسبه عوضته فيه الجنة. وهكذا الأفراط إذا احتسبهم والدهم، وأمهم كانوا لهم شفعاء، سواء كانوا ثلاثة أو أكثر، أو اثنين أما الواحد فلم يسألوه عنه -عليه الصلاة والسلام-، لكنه داخل في الصفي، إذا صبر واحتسب عوضه فيه الجنة، وإن كان واحدًا، نعم. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13403/هل-شفاعة-من-يموت-صغيرا-لاباىهم-خاصة-بالذكور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_562/56205.mp3","categories":["التوسل والشفاعة"]},{"id":15015,"question":"في سؤال السائل من جمهورية مصر العربية يقول: سماحة الشيخ، اختلط على كثير من الناس مفهوم التوسل الجائز، والتوسل الممنوع. نرجو من سماحة الشيخ أن يبين لنا ما هو التوسل؟ وما هو الجائز منه وما هو الممنوع؟ وأمثلة على ذلك؟مأجورين.","title":"حقيقة التوسل المشروع والممنوع","answer":"الجواب: التوسل كما ذكر ابن القيم وغيره -رحمة الله عليه-، التوسل أقسام ثلاثة:\nتوسل هو الشرك الأكبر: كدعاء الأموات، والاستغاثة بالأموات، والذبح لهم، والنذر لهم، هذا هو الشرك الأكبر، يقول المشركون: مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى [الزمر:3 ].. هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ [يونس:18]، يتوسلون بدعائهم، واستغاثتهم بهم، وهذا هو الشرك الأكبر. التوسل الثاني: التوسل بذواتهم، تقول: اللهم إني أسألك بذات فلان، أسألك بنبيك فلان، اللهم إني أسالك بعبادك الصالحين، اللهم إني أسألك بمحمد، بـموسى، هذا توسل ممنوع بدعة؛ لأنه وسيلة للغلو والشرك. التوسل الثالث: الجائز المشروع، وهو التوسل بأسماء الله وصفاته، التوسل بأعمالك الصالحة، بإيمانك، هذا التوسل المشروع، مثل ما قال الله -جل وعلا-: وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180] ومثلما كان النبي ﷺ يدعو الله بأسمائه وصفاته، هذا يقال له: التوسل المشروع، ومثلما في الحديث: أعوذ بعزتك أن تضلني. فالتوسل بصفات الله أمر مشروع: أسألك برحمتك، أسألك بعلمك، أسألك بإحسانك، أسألك بقدرتك أن تغفر لي، ومن حد دعاء الذي سأله؛ لما سأله عثمان بن أبي العاص، واشتكى إليه مرضًا، قال: «ضع يدك على ما تشتكي، وقل: أعوذ بالله بعزته وقدرته من شر ما أجد وأحاذر» فتوسل بعزة الله وقدرته من شر ما يجد ويحاذر، استعاذ بذلك، ومنه: اللهم إني أعوذ برضاك من سخطك، وبعفوك من عقوبتك، وبك منك، لا أحصي ثناء عليك. أما التوسل بالإيمان والأعمال الصالحة، والتقوى لله؛ فهذا هو التوسل الشرعي، فالتوسل بصفات الله، وبأسماء الله، وبإيمانك وتقواك، هذا التوسل الشرعي. أما التوسل بالذوات ذات فلان وذات فلان، أو جاه فلان، أو حق فلان؛ فهذا توسل بدعي، فلا يتوسل بجاه فلان، ولا بحق فلان، ولا بالنبي فلان، ولا بذات فلان؛ هذا توسل بدعي. أما التوسل بعلم الله، بطاعة الله، باتباعك لشرع الله، هذا كله لا بأس به، توسل بصفات الله، وتوسل بأسماء الله وصفاته: وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180]. ومنه: التوسل بالأعمال الصالحة، كأن تقول: اللهم إني أسألك بإيماني بك، بتوكلي عليك، بثقتي بك، ببري لوالدي، بأداء الأمانة، وما أشبه ذلك، هذا توسل شرعي، ومنه حديث أصحاب الغار الذين انطبقت عليهم الصخرة؛ فقالوا فيما بينهم: لن ينجيكم من هذا البلاء، إلا أن تسألوا الله بصالح أعمالكم، فسألوا الله بصالح أعمالهم، فقال أحدهم: اللهم إنه كان لي أبوان شيخان كبيران، وكنت لا أغبق قبلهما أهلًا ولا مالًا، فنأى بي طلب الشجر ذات ليلة؛ فلم أرح عليهما إلا وقد ناما، فوقفت على رؤوسهما والقدح في يدي؛ أنتظر استيقاظهما، ولم أستحسن استيقاظهما حتى برق الصبح، فلما استيقظا شربا غبوقهما، اللهم إن كنت تعلم أني فعلت هذا ابتغاء وجهك؛ فافرج عنا ما نحن فيه، فانفرجت الصخرة شيئًا لا يستطيعون الخروج منه، وقال الآخر: اللهم إنه كانت لي ابنة عم كنت أحبها كأشد ما يحب الرجال النساء، وإني راودتها عن نفسها فأبت، فألمت بها سنة -يعني: حاجة شديدة- فجاءت إليه تقول: يا ابن عم، أعني، فقال: لا حتى تمكنيني من نفسك، فطاوعته من أجل حاجتها، فلما جلس بين رجليها، قالت له: يا عبد الله، اتق الله ولا تفض الخاتم إلا بحقه، قال: فقمت عنها خوفًا منك، وهي أحب الناس إلي، اللهم إن كنت تعلم أني فعلت هذا ابتغاء وجهك فافرج عنا ما نحن فيه، فانفرجت الصخرة بعض الشيء، لكنهم لا يستطيعون الخروج، ثم قال الثالث: اللهم إني استأجرت أجراء، فأعطيت كل أجير حقه، إلا واحدًا ترك أجره، فنميته له، وثمرته له، حتى صار منه إبل وبقر وغنم وعبيد، فجاء إلي بعد ذلك وقال: يا عبدالله، أعطني أجري، فقلت له: كل ما ترى من أجرك من الإبل والبقر والغنم والعبيد، قال: يا عبدالله، لا تستهزئ بي، قلت: إني لا أستهزئ بك، إنه من أجرك نميته له، فخذه فاستاقه كله، اللهم إن كنت تعلم أني فعلت هذا ابتغاء وجهك، فافرج عنا ما نحن فيه، فانفرجت الصخرة حتى خرجوا هذا توسل من هؤلاء الثلاثة بأعمالهم الطيبة التي فعلوها لله ، فنفعهم الله بها عند الشدة، نعم. المقدم: أحسن الله إليكم سماحة الشيخ، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/13506/حقيقة-التوسل-المشروع-والممنوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_563/56302.mp3","categories":["التوسل والشفاعة"]},{"id":15042,"question":"يقول: كثير من الناس يقولون: الشفاعة يا محمد، هل هي شرك؟ وإن كانت شرك ماذا يقولون؟","title":"حكم طلب الشفاعة من النبي ﷺ","answer":"الجواب: طلب الشفاعة من النبي ﷺ، ومن غيره من الأموات لا يجوز، وهو شرك أكبر عند أهل العلم؛ لأنه لا يملك شيئًا بعدما مات -عليه الصلاة والسلام-، والله يقول: قُلْ لِلَّهِ الشَّفَاعَةُ جَمِيعًا [الزمر:44] الشفاعة ملكه ، والنبي ﷺ وغيره من الأموات لا يملكون التصرف بعد الموت في شفاعة، ولا في دعاء، ولا في غير ذلك، الميت إذا مات انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له. وإنما جاء أنها تعرض عليه الصلاة -عليه الصلاة والسلام-؛ ولهذا قال: فإن صلاتكم تبلغني حيث كنتم، صلوا علي؛ فإن صلاتكم تبلغني حيث كنتم وأما حديث أنه تعرض عليه الأعمال، فما وجد فيها من خير حمد الله، وما وجد فيها من شر استغفر لنا؛ فهو حديث ضعيف لا يصح عن النبي ﷺ، ولو صح لم يكن فيه دلالة على أنا نطلب منه الشفاعة. فالحاصل: أن طلب الشفاعة من النبي ﷺ، أو من غيره من الأموات؛ أمر لا يجوز، وهو على القاعدة الشرعية من الشرك الأكبر؛ لأنه طلب من الميت شيئًا لا يقدر عليه، كما لو طلب منه شفاء المريض، أو النصر على الأعداء، أو غوث المكروبين، أو ما أشبه ذلك، فكل هذا من أنواع الشرك الأكبر، ولا فرق بين طلب هذا من النبي ﷺ، أو من الشيخ عبدالقادر ، أو من فلان، أو فلان، أو من البدوي، أو من الحسين، أو غير ذلك، طلب هذا من الموتى أمر لا يجوز، وهو من أقسام الشرك، وإنما الميت يترحم عليه، إذا كان مسلمًا، ويدعى له بالمغفرة والرحمة، والنبي ﷺ إذا سلم عليه مسلم يصلي عليه -عليه الصلاة والسلام-، ويدعو له، أما أن يطلبه المدد، أو الشفاعة، أو النصر على الأعداء، كل هذا لا يجوز، وهذا من عمل أهل الجاهلية، ومن عمل أهل الشرك. فيجب على المسلم أن ينتبه لهذا، وأن يحذر مثل هذا، نعم.","link":"https://binbaz.org.sa/fatwas/13557/حكم-طلب-الشفاعة-من-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_654/nour_65403.mp3","categories":["التوسل والشفاعة"]},{"id":16927,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (ع. ف. غ) أخونا ضمن رسالته أكثر من ثلاثين سؤالًا، يقول: إنه اقتبسها من واقع الناس، وهي -فيما يقول:- أسئلة هامة، ولا سيما فيما يتعلق بأمر العقيدة، لخصت أسئلته سماحة الشيخ على النحو التالي: في سؤاله الأول يقول: حدثونا عن التوسل، والوسيلة؟ ووضحوا لنا الشبهات، والرد عليها، ولا سيما وأن هناك من يستدل بمثل قوله تعالى: وَابْتَغُوا إِلَيْهِ الْوَسِيلَةَ [المائدة:35] ويستدلون أيضًا بالتوسل بـالعباس ؟ وما الفرق بين التوسل بالأنبياء والصالحين، والتوسل بالأعمال الصالحة؟ جزاكم الله خيرًا.","title":"التوسل والوسيلة بين المشروع والممنوع","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله سلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فهذا السؤال سؤال مهم، وجدير بالعناية؛ لأنه يشتبه الموضوع على كثير من الناس. فالوسيلة وسيلتان: وسيلة جائزة، بل مشروعة مأمور بها، ووسيلة ممنوعة. أما الوسيلة المشروعة: فهي التوسل إلى الله بالإيمان، والعمل الصالح، وسائر ما شرعه الله -جل وعلا- وهي المراد في قوله سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَابْتَغُوا إِلَيْهِ الْوَسِيلَةَ [المائدة:35]، يعني: القربة إليه بطاعته: كالصلاة، والصوم، والصدقة، والحج، وإخلاص العبادة لله، ونحو ذلك، فقوله سبحانه: قُلِ ادْعُوا الَّذِينَ زَعَمْتُمْ مِنْ دُونِهِ [الإسراء:56] يعني: من دون الله، من أصنام، وأشجار، وأحجار، وأنبياء، وغير ذلك، فَلا يَمْلِكُونَ كَشْفَ الضُّرِّ عَنكُمْ وَلا تَحْوِيلًا [الإسراء:56] يعني: أولئك المدعوون لا يملكون كشف الضر عن داعيهم من مرض، أو جنون، أو غير ذلك وَلَا تَحْوِيلًا يعني: ولا تحويله من حال إلى حال، من شدة إلى سهولة، أو من عضو إلى عضو، لا يملكون ذلك، بل هم عاجزون عن ذلك، وإنما هو بيد الله . ثم قال: أُوْلَئِكَ الَّذِينَ يَدْعُونَ [الإسراء:57] يعني: أولئك الذين يدعوهم هؤلاء المشركون من أنبياء، أو صالحين، أو ملائكة يَبْتَغُونَ إِلَى رَبِّهِمُ الْوَسِيلَةَ [الإسراء:57] يعني: هم يبتغون ليطلبوا من الله الوسيلة، وهي القربة إليه بطاعته من صلاة، وصوم، وصدقات، وغير ذلك وَيَرْجُونَ رَحْمَتَهُ [الإسراء:57] ولهذا عملوا، واجتهدوا في طاعته، ويخافون عذابه . فهذه الوسيلة هي القيام بحقه من توحيده، وطاعته، بفعل الأوامر، وترك النواهي، وهي الإيمان، والهدى، والتقوى، وهي ما بعث الله به الرسل -عليهم الصلاة والسلام- من قول وعمل. فهذه الوسيلة واجبة في الواجبات، مستحبة في المستحبات، فالتوسل إليه بتوحيده، والإخلاص له، وإقام الصلاة، وإيتاء الزكاة، وصوم رمضان، وحج البيت، هذا أمر لازم، وفريضة في الحجة الأولى من العمر، وكذلك التوسل إليه بترك المعاصي، أمر لازم، فريضة. والتوسل إليه بالنوافل مثل صلاة النافلة، وصوم النافلة، وصدقة النافلة، والإكثار من ذكر الله أيضًا مستحب، وقربة، وطاعة، وذلك جعله الله من أسباب دخول الجنة، والنجاة من النار. أما الوسيلة الأخرى التي لا تجوز: فهي التوسل إليه بدعاء الأموات، والاستغاثة بالأموات، فهذه الوسيلة شركية، يسميها المشركون: وسيلة، وهي شرك أكبر، وهي المراد في قوله سبحانه: وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لا يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَيَقُولُونَ هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ [يونس:18] ويقول -جل وعلا-: وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى [الزمر:3] يعني: يقولون: ما نعبدهم إلا ليقربونا زلفى، فاتخذوهم وسيلة بهذا المعنى، يعني: بدعائهم، وسؤالهم، وطلب الشفاعة منهم، والنصر على الأعداء، وشفاء المرضى، ونحو ذلك، وزعموا أنهم بهذا يكونون لهم وسيلة، وهذا هو الشرك الأكبر، وهذا هو دين المشركين، نسأل الله العافية. فإن المشركين يزعمون أن عبادتهم للأنبياء، والملائكة، والصالحين، والجن وسيلة إلى مقاصدهم، وأن هذه المعبودات تشفع لهم عند الله، وتقربهم إلى الله زلفى، فأبطل الله ذلك، وأكذبهم في ذلك، قال تعالى .. جاء في حقهم: قُلْ أَتُنَبِّئُونَ اللَّهَ بِمَا لا يَعْلَمُ فِي السَّمَوَاتِ وَلا فِي الأَرْضِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ [يونس:18] بعد قوله سبحانه: وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لا يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَيَقُولُونَ هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ [يونس:18] أبطل الله ذلك بقوله: قُلْ أَتُنَبِّئُونَ اللَّهَ يعني: تخبرون الله بِمَا لا يَعْلَمُ فِي السَّمَوَاتِ وَلا فِي الأَرْضِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ [يونس:18]. وقال في آية الزمر: فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ ۝ أَلا لِلَّهِ الدِّينُ الْخَالِصُ وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ يعني: يقولون: مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى [الزمر:2-3] فأكذبهم الله بقوله سبحانه: إِنَّ اللَّهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ إِنَّ اللَّهَ لا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّارٌ [الزمر:3] فسماهم كذبة في قولهم: إنها تقربهم إلى الله زلفى، كفرة بهذا العمل، بدعائهم إياهم، واستغاثتهم بهم، ونذرهم لهم، وذبحهم لهم، ونحو ذلك. فالواجب على جميع المكلفين، بل على جميع الناس الحذر من هذه الوسيلة، فلا يفعلها المكلف، ولا غير المكلف، يجب على المكلف أن يحذرها، وعليه أن يحذر غير المكلفين من أولاده أن يفعلها أيضًا، فالله هو الذي يعبد  هو الذي يدعى، هو الذي يرجى، هو الذي يسأل النصر على الأعداء، والشفاء للمرضى، وغير ذلك من حاجات العباد، يقول  في كتابه العظيم: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ ۝ مَا أُرِيدُ مِنْهُمْ مِنْ رِزْقٍ وَمَا أُرِيدُ أَنْ يُطْعِمُونِ ۝ إِنَّ اللَّهَ هُوَ الرَّزَّاقُ ذُو الْقُوَّةِ الْمَتِينُ [الذاريات:56-58] ويقول سبحانه: يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ وَالَّذِينَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ [البقرة:21] ويقول عن نبيه ﷺ: قُلْ لا أَمْلِكُ لِنَفْسِي نَفْعًا وَلا ضَرًّا إِلَّا مَا شَاءَ اللَّهُ وَلَوْ كُنتُ أَعْلَمُ الْغَيْبَ لاسْتَكْثَرْتُ مِنَ الْخَيْرِ وَمَا مَسَّنِيَ السُّوءُ إِنْ أَنَا إِلَّا نَذِيرٌ وَبَشِيرٌ لِقَوْمٍ يُؤْمِنُونَ [الأعراف:188] فهو نذير وبشير، ليس بمعبود من دون الله، وليس بإله مع الله  وقال -جل وعلا-: وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا ۝ وَأَنَّهُ لَمَّا قَامَ عَبْدُ اللَّهِ يَدْعُوهُ [الجن:18-19]، يعني: محمدًا ﷺ كَادُوا يَكُونُونَ عَلَيْهِ لِبَدًا ۝ قُلْ إِنَّمَا أَدْعُو يعني: قل يا محمد للناس قُلْ إِنَّمَا أَدْعُو رَبِّي وَلا أُشْرِكُ بِهِ أَحَدًا ۝ قُلْ إِنِّي لا أَمْلِكُ لَكُمْ ضَرًّا وَلا رَشَدًا ۝ قُلْ إِنِّي لَنْ يُجِيرَنِي مِنَ اللَّهِ أَحَدٌ وَلَنْ أَجِدَ مِنْ دُونِهِ مُلْتَحَدًا ۝ إِلَّا بَلاغًا مِنَ اللَّهِ وَرِسَالاتِهِ [الجن:19-23] بل ذلك بيده  هذه الأمور بيد الله هو الذي يملك النفع والضر، والعطاء والمنع، والشفاء من الأمراض، والنصر على الأعداء، هو بيده . وهناك نوع ثانٍ من الوسيلة الممنوعة: هو التوسل بجاه فلان وحق فلان، هذه الوسيلة وسيلة ممنوعة، لكنها ليست شركًا أكبر، بل هي من وسائل الشرك، كأن يقول: اللهم إني أسألك بجاه محمد، أو بجاه فلان، أو بحق أنبيائك، هذا لا يجوز، هذه بدعة ليس عليها دليل، الله يقول: وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180]، يدعى بأسمائه وصفاته. وهكذا يتوسل إليه بالأعمال الصالحة مثل: .. الصلاة، والصوم، بر الوالدين، صلة الرحم، العفة عن الفواحش، هذه وسائل شرعية، كما في قصة أصحاب الغار الذين آواهم المبيت، والمطر إلى غار، فدخلوا فيه، فانطبقت عليهم صخرة سدت عليهم فم الغار، فقالوا فيما بينهم: لن ينجيكم من هذا إلا أن تدعو الله بصالح أعمالكم، فسألوا الله، وتوجهوا إليه بصالح أعمالهم، فأحدهم دعا وسأل ربه ببره لوالديه، والآخر توسل إلى الله بعفته عن الزنا بعد قدرته على المرأة، والثالث توسل إلى الله بأداء الأمانة لأجير كان له أجر عنده، فنمى أجره، فلما جاء أعطاه إياه كاملًا، فانفرجت عنهم الصخرة بهذه الوسيلة الصالحة العملية. لما دعا الأول، وسأل ربه ببره لوالديه، وأنه كان له أبوان شيخان كبيران، لا يغبق قبلهم أهلًا، ولا مالًا، وأنه نأى به طلب الشجر ذات ليلة، فتأخر عليهما، فجاء إليهما بغبوقهما، فوجدهما نائمين، فمكث والقدح على يده ينتظر استيقاظهما، ولم يغبق أهله، ولا أولاده، بل صبر، ولم ير إيقاظهما؛ لئلا يكدر عليهما نومهما، فصبر حتى استيقظا عندما برق الصبح، فسقاهما غبوقهما، ثم قال في دعائه: اللهم إن كنت تعلم أني فعلت هذا ابتغاء وجهك؛ فافرج عنا ما نحن فيه؛ فانفرجت الصخرة شيئًا لا يستطيعون معه الخروج.  ثم دعا الثاني بأنه كانت له ابنة عم يحبها، كأشد ما يحب الرجال النساء، وأنه أرادها عن نفسها يعني: الفاحشة، فأبت عليه، فألمت بها سنة حاجة، فجاءت إليه تطلب منه العون، فقال: لا حتى تمكنيني من نفسك؛ فوافقت على ذلك بسبب شدة حاجتها، فخاف من الله، وترك الزنا، وترك لها الذهب، ثم قال: اللهم إن كنت تعلم أني فعلت هذا ابتغاء وجهك؛ فافرج عنا ما نحن فيه، يعني: تركت الفاحشة مع القدرة خوف الله، فانفرجت الصخرة بعض الشيء، لكن لا يستطيعون الخروج.  ثم دعا الثالث فقال: اللهم إنه كان لي أجراء، يعني: عمال لهم أجر، فأعطيت كل عامل أجره، إلا واحدًا بقي له أجره، فنميته له، فاشتريت منه إبلًا وبقرًا وغنمًا ورقيقًا، ثم جاءني فقال: يا عبدالله! أعطني أجري، فقلت له: هذا كله من أجرك، فقال: يا عبدالله! لا تستهزئ بي، فقلت له: إني لا أستهزئ بك هو مالك، فاستاقه كله، اللهم إن كنت تعلم أني فعلت هذا ابتغاء وجهك؛ فافرج عنا ما نحن فيه، فانفرجت الصخرة، وخرجوا يمشون. هذا من لطف الله، ومن إحسانه -جل وعلا- ومن آياته العظيمة، أن فرج عنهم، وجعل انطباق هذه الصخرة سببًا لتوسلهم بهذه الأعمال؛ ليعلم الناس فضل الأعمال الصالحة، وأنها من أسباب تفريج الكروب، وتيسير الأمور، وأن الواجب على العبد أن يحذر غضب الله، وأسباب عقابه، متى قدر على المعصية؛ فليحذر، وليبتعد عنها، ومتى قدر على البر، والخير؛ فليفعل. أما توسل عمر  بـالعباس، فهذا توسل بدعائه، بدعاء العباس، فإنه كان النبي ﷺ إذا أجدب الناس كان يسأل الله  الغيث، وكان الناس يفزعون إليه، ويقولون: يا رسول الله! استغث لنا، هلكت الأموال، وانقطعت السبل، يعني: بسبب الجدب، فيستغيث الله، ويسأله سبحانه أن يغيث العباد؛ فيغيثهم  فلما أجدبوا في عهد عمر؛ قال: \"اللهم إنا كنا نتوسل إليك بنبينا حين كان بين أيدينا، فتسقينا، وإنا نتوسل إليك بعم نبينا فاسقنا، قم يا عباس! فادع الله لنا، فقام العباس، ودعا لهم، واستغاث؛ فسقاهم الله\" والعباس عم النبي ﷺ هذا توسل بدعاء العباس، مثل ما كانوا يتوسلون بدعاء النبي في حياته ﷺ فدل ذلك على أنه بعد وفاته لا يستغاث به، ولا يطلب منه الغوث -عليه الصلاة والسلام- لأنه لا يستطيع ذلك، انقطع عمله المتعلق بالدنيا، ولهذا طلب عمر  من العباس أن يدعو الله، وأن يغيث الناس، فقام العباس، ودعا الله، فأغاث الله الناس. وهكذا فعل معاوية  في الشام مع يزيد بن الأسود، طلب من يزيد بن الأسود الصحابي الجليل أن يسأل الله الغوث، فقام يزيد، وسأل الله، فأغاث الناس، هذا لا بأس به، هذه الاستغاثة لا بأس بها شرعية، أن يقول ولي الأمر، أو خطيب المسجد العالم من العلماء، أو بعض الأخيار: ادع الله يا فلان للمسلمين أن الله يغيثهم؛ فلا بأس، كما فعل عمر مع العباس، وكما فعل معاوية مع يزيد بن الأسود . وهكذا الإنسان يقول: اللهم إني أسألك بأسمائك الحسنى، وصفاتك العلى أن تغيثنا.. أن ترحمنا.. أن تنزل علينا المطر.. أن تغفر لنا، الله يقول سبحانه: وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180] فأنت تسأل، وهكذا غيرك يسأل، يتوسل إلى الله بأسمائه وصفاته، ويدعو الله للمسلمين في وقت الجدب، وفي غيره. وبهذا يتضح أن الوسيلة ثلاثة أقسام: قسم مشروع: وهو التوسل إلى الله بتوحيده، والإيمان به، والأعمال الصالحات، وبأسمائه وصفاته. وقسم شرك: وهو التوسل إلى الله بدعاء الأموات، والاستغاثة بالأموات، والنذر لهم، والذبح لهم، أو التوسل بالأصنام، أو بالأشجار، والأحجار، أو بالجن، فهذا شرك أكبر. القسم الثالث: بدعة، لا يجوز، وليس بشرك، وليس مشروعًا، بل هو بدعة، وهو التوسل بحق فلان، أو جاه فلان، أو بجاه النبي، أو بجاه فلان، أو حق الأنبياء، هذا هو المنكر، وهذا بدعة، ومن وسائل الشرك. ومن الوسائل الشرعية -كما تقدم-: التوسل بالأعمال الصالحات -كما تقدم- التوسل بأسماء الله وصفاته، والتوسل بالأعمال الصالحات، هذا كله توسل مشروع، نعم. المقدم: جزاكم الله خيرًا، هل يتعرض سماحتكم لشبه أولئك الذين يتوسلون بالمخلوقين؟ الشيخ: هذه الشبه لا أساس لها، بل هي باطلة، بعضهم يشبه، يقول: إذا جاز التوسل بجاه فلان، أو حق فلان؛ دل على أنه يدعى، ويسأل، هذا باطل؛ لأن التوسل بالجاه ما هو بجائز بدعة، ثم لو جاز ما صلح أن يكون دليلًا على أن يستغاث بالإنسان؛ لأن التوسل بالجاه سؤال لله، يسأل من الله بجاه فلان، فهذا سؤال لله، ليس سؤال لمخلوق، لكن الوسيلة هي التي منكرة، بدعة بجاه فلان وحق فلان. أما لو سأل الله بأسمائه وصفاته، أو سأل الله، ولم يتوسل بشيء قال: اللهم أنجنا من النار.. اللهم أغثنا.. اللهم أغثنا، كله طيب، وإذا قال: اللهم أغثنا بفضلك.. بأسمائك وصفاتك.. برحمتك طيب. أما الشبهة بأن الأنبياء لهم جاه، ولهم عند الله منزلة؛ فندعوهم حتى يشفعوا لنا، هذا باطل؛ لأن جاههم، ومنزلتهم التي عند الله لم يجعلها الله مسوغة للمشركين أن يعبدوهم مع الله، قد أنكر عليهم لما استغاثوا بهم، وطلبوهم الشفاعة، وطلبوهم أن يقربوهم إلى الله زلفى؛ أنكر عليهم ذلك، وسماهم: كذبةً كفرة، وأخبر أن ما فعلوه باطل يتنزه الله عنه، في قوله : قُلْ أَتُنَبِّئُونَ اللَّهَ بِمَا لا يَعْلَمُ فِي السَّمَوَاتِ وَلا فِي الأَرْضِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ [يونس:18] وقال : إِنَّ اللَّهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ إِنَّ اللَّهَ لا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّارٌ [الزمر:3].  فهذه الوسيلة التي فعلها المشركون مع الأصنام، ومع الأنبياء، ومع الجن، واستغاثوا بهم، ونذروا لهم، وزعموا أنهم يشفعون لهم، هذه باطلة، أبطلها الله، وأبطلها الرسول ﷺ وحذر منها الأمة، وأمرهم أن يخصلوا العبادة لله وحده  نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15706/التوسل-والوسيلة-بين-المشروع-والممنوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_827/nour_82701.mp3","categories":["التوسل والشفاعة"]},{"id":17327,"question":"أخيرًا يسأل سماحتكم فيقول: ما الفرق بين التوسل، والوسيلة؟","title":"الفرق بين التوسل والوسيلة","answer":"الجواب: التوسل: دعاء الشخص، يقال: توسل، دعا، يقال: أسألك بأسمائك هذا توسل، أسألك بإيماني بك هذا توسل، والوسيلة هي الإيمان، والتقوى، والأسماء الحسنى وسيلة إلى الله -جل وعلا- الدعاء بها وسيلة، وأنت المتوسل، التوسل دعاؤك والوسيلة ما دعوت به. فإذا قلت: اللهم إني أسألك بأسمائك الحسنى، وصفاتك العلى أن تغفر لي، فأنت بدعائك متوسل، وهذا الدعاء يسمى توسلًا، والمدعو به هو بأسمائه، وصفاته هذا يقال له: وسيلة، يعني: الدعاء بالأسماء، والصفات وسيلة، وهذا هو نفس الدعاء يسمى توسلًا، والمتوسل به: هو الإيمان أو الأسماء، والصفات، أو أعمالك الأخرى الصالحة. المقدم: جزاكم الله خيرًا، و أحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16157/الفرق-بين-التوسل-والوسيلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_724/nour_72407.mp3","categories":["التوسل والشفاعة"]},{"id":17613,"question":"رسالة وصلت إلى البرنامج من المستمع علي عبد الجبار يقول: ما حكم الوجاهة؟ وهل يصح أن نقول: بجاه سيدنا محمد ﷺ اغفر لي أو اغفر لوالدي وما أشبه ذلك؟","title":"حكم سؤال الله بجاه النبي وغيره","answer":"الجواب: السؤال بالجاه بدعة لا يجوز، ولكن تسأل الله بأسمائه الحسنى وصفاته العلى وبإيمانك وأعمالك الصالحة هذا المشروع، أما أن تقول: اللهم إني أسألك بجاه محمد ﷺ، أو بجاه نبينا محمد ﷺ، أو بجاه الأنبياء أو بجاه الصالحين هذا منهي عنه ليس من الوسائل الشرعية، الله يقول جل وعلا يقول: وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180]، ما قال: فادعوه بجاه الأنبياء أو بجاه الصالحين، قال: وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180].\nفتقول: اللهم إني أسألك بأسمائك الحسنى أن تغفر لي.. أن ترحمني.. أن تعلمني العلم النافع.. أن تفقهني في الدين.. أن تغنيني عن خلقك.. وما أشبه ذلك.\nاللهم إني أشهد بأنك الرحمن الرحيم بأنك العزيز الحكيم أن تغفر لي وترحمني، اللهم إني أسألك برحمتك وفضلك وإحسانك أن تغفر لي وترحمني، اللهم إني أسألك بأنك الجواد الكريم، بأنك العفو الغفور.. إلى غير هذا، مثلما في الحديث الصحيح.\nالنبي ﷺ قال للصديق ، لما قال الصديق: يا رسول الله! علمني دعاء أدعو به في صلاتي وفي بيتي، قال: قل: اللهم إني ظلمت نفسي ظلمًا كثيرًا ولا يغفر الذنوب إلا أنت فاغفر لي مغفرة من عندك وارحمني إنك أنت الغفور الرحيم، هكذا علم الصديق رواه الشيخان في الصحيحين.\nوكان النبي ﷺ يدعو ربه يقول: اللهم اغفر لي ذنبي كله دقه وجله وأوله وآخره وعلانيته وسره ويدعو الله بأسمائه  وصفاته، فلا ينبغي لأحد أن يدعو الله بغير ما شرع لا بجاه فلان ولا بحق فلان، لا بحق الأنبياء والصالحين ولا بجاه الأنبياء والصالحين. ولا بأس أن تتوسل بالإيمان تقول: اللهم إني أسألك بإيماني بك وبنبيك محمد ﷺ أن تغفر لي أو أن تعطيني كذا وكذا.. اللهم إني أسألك بمحبتي لك ومحبتي لنبيك ولعبادك الصالحين أن تغفر لي وترحمني لا بأس، التوسل بالإيمان والمحبة لله ولرسوله أو بالتوحيد تقول: اللهم إني أسألك بأني أشهد أنك أنت الله لا إله إلا أنت، كما فعله النبي ﷺ قال: اللهم إني أسألك بتوحيدي لك وإيماني بك، وهكذا بالأعمال الصالحة الأخرى تقول: اللهم إني أسألك ببري لوالدي وبأدائي الأمانة وبعفتي عما حرم الله، تسأله بأعمالك الطيبة كله طيب.\nأما أن تسأله بجاه فلان ما هو بعمل لك هذا، حق فلان ما هو بعمل لك ولا هو من أسماء الله وصفاته ولا تسأل به، وقد ثبت في الصحيحين عن النبي ﷺ أنه قال: إن ثلاثة ممن كان قبلنا -ثلاثة من الأمة قبلنا- آواهم المبيت والمطر إلى غار فدخلوا فيه من أجل المبيت والوقاية من المطر- فأراد الله جل وعلا أن أنزل عليهم صخرة انحدرت عليهم بإذن الله فغطت عليهم باب الغار- عظيمة ما استطاعوا دفعها- فقالوا فيما بينهم: لن ينجيكم من هذه الصخرة إلا أن تدعو الله بصالح أعمالكم.\nالله جل وعلا قدر سقوط هذا الحجر على فم الغار ليتوسلوا هذه الوسائل وليعلم الناس فضل البر وفضل العفة عن الفواحش وفضل أداء الأمانة، الله جل وعلا قدر سقوط هذا الحجر على فم الغار ليتوسلوا هذه الوسائل وليعلم الناس فضل البر وفضل العفة عن الفواحش، وفضل أداء الأمانة حتى يتأسوا بهؤلاء ويستفيدوا من عمل هؤلاء، هذه نعمة من الله فضل من الله والنبي ﷺ خبرنا بهذا حتى نستفيد من هذه القصة وأن بر الوالدين والعفة عن الفواحش وأداء الأمانة من أعظم الأسباب في تفريج الكروب وتيسير الأمور ومن أعظم الأسباب في النجاة من النار؛ لأن الكربة يوم القيامة أعظم من كربة الدنيا.\nفالإنسان إذا اتقى الله وابتعد عن محارم الله وأدى ما أوجب الله عليه فهذا من أسباب التفريج في الدنيا والنجاة في الآخرة، كما قال سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3]، وقال سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]. فأنت يا عبد الله وأنت يا أمة الله تفكرا جميعًا في هذه القصة، قصة هؤلاء الثلاثة، واستفيدا من هذه القصة الفائدة العظيمة وليتيقن كل واحد منا أن بر الوالدين من أعظم القربات ومن أفضل الطاعات، من أسباب تفريج الكروب وتيسير الأمور، وهكذا العفة عما حرم الله عن الزنا والفواحش من أفضل القربات ومن أعظم أسباب تيسير الأمور وتفريج الكروب والنجاة من النار، وهكذا أداء الأمانة والعناية بالأمانة وعدم الخيانة، كل ذلك من أسباب تفريج الكروب وتيسير الأمور.\nومن أسباب رضا الله سبحانه، من أسباب رضا الله وتيسيره أمرك وإدخالك الجنة وإنجائك من النار، نسأل الله للجميع التوفيق والهداية. نعم.\nالمقدم: جزاكم الله خيرًا وبارك في علمكم.","link":"https://binbaz.org.sa/fatwas/16541/حكم-سوال-الله-بجاه-النبي-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_842/nour_84204.mp3","categories":["التوسل والشفاعة"]},{"id":17644,"question":"من أسئلة هذا السائل يقول يا سماحة الشيخ: ما هو التوسل المشروع وغير المشروع؟","title":"الفرق بين التوسل المشروع والممنوع","answer":"الجواب: التوسل المشروع التوسل بأسماء الله وصفاته، والإيمان به وتوحيده والإخلاص له، هذا هو التوسل المشروع، قال الله تعالى: وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا[الأعراف:180] والتوسل بالأعمال الصالحة كما توسل في الغار ثلاثة: واحد توسل ببره لوالديه، والثاني توسل بعفته عن الزنا، والثالث توسل بأدائه الأمانة، فالتوسل بأسماء الله وصفاته وتوحيده والإيمان به والأعمال الصالحة، كله طيب، مثل: اللهم إني أسألك بأني أشهد أنك أنت الله لا إله إلا أنت الأحد الصمد، هذا توسل بالتوحيد، اللهم إني أسألك بإيماني بك وبمحبتي لك ومحبتي لرسلك، اللهم إني أسألك بحبي للصلاة، بمحافظتي على الصلاة وما أشبه ذلك.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16571/الفرق-بين-التوسل-المشروع-والممنوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59420.mp3","categories":["التوسل والشفاعة"]},{"id":18833,"question":"على بركة الله، نبدأ هذا اللقاء بسؤال السائل من السودان علي محمد الطيب، يقول في هذا  سماحة الشيخ، ما هو التوسل؟ وهل يصح العمل به؟ عندما يقول العبد طالبًا من ربه: اللهم ارحمني وارزقني بجاه المصطفى ﷺ، وربما البعض من الإخوة في الإسلام يذهب للشيخ يقول له مثلًا: اسأل لنا الله  في بعض الأمور. فما حكم الشرع في نظركم سماحة الشيخ في هذه القضية؟","title":"التوسل المشروع والممنوع","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. أما بعد: فالتوسل أقسام: أقسام ممنوعة، وأقسام جائزة: فالأقسام الممنوعة: كالتوسل الذي هو شرك، يسميه المسلمون توسلاً وهو دعوة الأموات، والاستغاثة بالأموات، والنذر لهم هذا يسميه المسلمون توسلاً وهو شرك أكبر، فالواجب الحذر منه، دعوة الميت، والاستغاثة به، والنذر له ونحو ذلك هذا كله من الشرك الأكبر وإن سماه توسلاً، قال-تعالى-: وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لا يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَيَقُولُونَ هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ[يونس:18]، ويقول : وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى[الزمر:3]. والنوع الثاني: شرك أصغر، وهو التوسل بجاه فلان، وبفلان، كالتوسل بجاه النبي محمد، أو بجاه الأنبياء، أو بجاه الشيخ عبد القادر، أو بجاه أبي بكر، أو عمر، أو بذواتهم أسألك بعمر، أو بعثمان، هذا من التوسل الذي هو منكر، وهو يسمى شركاً أصغر، وهو من وسائل الشرك الأكبر، هذا من وسائل الشرك الأكبر. وهناك توسل ثالث جائز: وهو توسل بدعاء الحي وطلب أن يدعو لك، مثلما قال الرجل للرسول: يا رسول الله! ادع الله لي، أن يرد الله علي بصري، تقول لأخيك: ادع الله لي أن يشفيني، فهذا توسل بدعائه، بدعائه لك وهو حي موجود هذا جائز، توسل جائز، تقول: يا أخي ادع الله أن يشفيني، ادع الله أن يرزقني ولد، ادع الله أن يغنيني من الفقر، مثلما يروى عن النبي ﷺ أنه قال لعمر لما ذهب للعمرة: لا تنسانا من دعائك، رواه الترمذي وجماعة في سنده ضعف، ومثل هذا يقول رسول الله ﷺ يقول للصحابة: إنه يقدم عليكم رجل من اليمن، يقال له أويس القرني، كان براً بأمه فمن لقيه منكم، فليطلب منه أن يستغفر له. أما التوسل الشرعي: هو التوسل بأسماء الله وصفاته وتوحيده والإيمان به، هذا توسل شرعي، تقول: اللهم إني أسألك بتوحيدك واتباعي لنبيك، وطاعتي لك أن تغفر لي، اللهم إني أسألك بأسمائك الحسنى وصفات العلى، اللهم إني أشهد أنك الرحمن الرحيم، بأنك الرب الكريم، بأنك خالق كل شيء، فالتوسل بالله وبأسمائه وصفاته هذا مشروع، ومن هذا قول النبي ﷺ: اللهم إني أسألك بأني أشهد أنك الله لا إله إلا أنت الأحد الصمد...، هذا كله من التوسل الشرعي، اللهم إني أسألك بإيماني بك ومحبتي لنبيك أن تغفر لي، ومن هذا قوله ﷺ في تعليمه لبعض الصحابة لما علمهم أن يتوسلوا علمهم أن يقولوا: اللهم إني أسألك بأني أشهد أنك أنت الله لا إله إلا أنت، وفي اللفظ الآخر: اللهم إني أشهد أن لك الحمد لا إله إلا أنت المنان بديع السموات والأرض يا ذا الجلال والإكرام يا حي يا قيوم كل هذا توسل بأسمائه وصفاته، والنبي ﷺ أقر الصحابة على ذلك وذكر بأن هذه التوسلات من أسباب الإجابة في بعضها لقد سأل الله باسمه الأعظم، فالتوسل بتوحيد الله، والإيمان بالله وبأسماء الله وبصفات الله توسل شرعي، من أسباب الإجابة.","link":"https://binbaz.org.sa/fatwas/17976/التوسل-المشروع-والممنوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_792/nour_79201.mp3","categories":["التوسل والشفاعة"]},{"id":19055,"question":"[هل تجوز الصلاة خلف من يتوسل بجاه النبي ﷺ]؟","title":"حكم الصلاة خلف من يتوسل بجاه المصطفى ﷺ","answer":"الجواب: ....... عند أهل العلم، عند جمهور أهل العلم بدعة لا يجوز؛ لأن الله ما شرعه لنا والتوسل ...........\nاللهم إني أسألك بأني أشهد أنك أنت الله لا إله إلا أنت .......... فسألوا الله بصالح أعمالهم فأزاحها عنهم  وهذا ثابت في الصحيحين من حديث ابن عمر رضي الله تعالى عنهما عن النبي عليه الصلاة والسلام، أحدهم توسل ببره لوالديه، والثاني توسل بأدائه الأمانة، والثالث توسل بعفته عن الزنا، فأزاح الله عنهم ....... .... إلى الله . أما التوسل بجاه فلان وحق فلان فهذا ليس بمشروع، ولكن تصح الصلاة خلف من فعله لأنه ليس بكافر إنما هو عاص ........ محدث فلا يجوز فعله، ثم هو وسيلة إلى الغلو، وسيلة إلى الغلو والشرك، فينبغي تركه، والنبي ﷺ ........ عليه الصلاة والسلام في حياته، وقد فعلوا ذلك في خطبة الجمعة استغاث لهم وأغاثهم الله، وقد طلبوا منه الاستغاثة، وخرج بهم إلى الصحراء، وصلى بهم ركعتين، واستغاث لهم فأغاثهم الله، وهكذا فعل عمر لما أجدبوا في عهد عمر قال: «اللهم إنا كنا إذا ..... » ........ التوسل بالنبي ﷺ وبـالعباس إنما هو بالدعاء طلبوه من أجل يدعو لهم فدعا لهم عليه الصلاة والسلام، وهكذا عمر طلب من العباس أن يدعو ويستغيث ففعل العباس ودعا، وأمن المسلمون؛ فأغاثهم الله، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18225/حكم-الصلاة-خلف-من-يتوسل-بجاه-المصطفى-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_928/nour_92808.mp3","categories":["صلاة الجماعة","التوسل والشفاعة"]},{"id":19460,"question":"يسأل أحد الإخوة المستمعين هذا السؤال، ويقول: هل يجوز الدعاء بجاه الرسول محمد ﷺ أو بجاه القرآن، أو بجاه الإنجيل والتوراة، أو بجاه رمضان، أو بجاه الصالحين من الناس؟","title":"حكم التوسل بجاه الأنبياء والصالحين وبجاه القرآن","answer":"الجواب: ليس للمسلم أن يدعو متوسلاً بجاه فلان، أو حق فلان كجاه الأنبياء، أو جاه الصالحين، أو جاه النبي محمد ﷺ أو جاه جبرائيل، أو حق فلان ليس هذا بمشروع عند جمهور أهل العلم، بل هو من البدع ومن وسائل الشرك. أما التوسل بالقرآن الكريم كأن يقول: أسألك يا رب! بكلامك أو بكتابك العزيز فلا بأس، أو أسألك بكلامك المنزل على موسى أو على عيسى فلا بأس، لكن التوسل بأسماء الله وصفاته أكمل، أسألك بأسمائك يا رب! وبصفاتك، والقرآن من كلامه والتوراة من كلامه، والإنجيل من كلامه المنزل لا المحرف، الكلام المنزل على موسى من كلام الله والكلام المنزل على عيسى من كلام الله. فإذا توسل المؤمن بكلام الله المنزل على أنبيائه فلا بأس أو بالقرآن نفسه فلا بأس؛ لأنه من صفاته سبحانه وتعالى، وإذا قال: أسألك بأسمائك الحسنى أو بصفاتك العلى مجملاً فهذا كله طيب، وكلها وسائل شرعية كما قال تعالى: وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180]. وهكذا التوسل بالإيمان بالله ورسوله، بمحبة الله ورسوله، والتوسل بأعمالك الصالحة، كالتوسل ببرك لوالديك، بعفتك عما حرم الله بأدائك الأمانة التي عليك، التوسل بالأعمال الصالحات لا بأس. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18687/حكم-التوسل-بجاه-الانبياء-والصالحين-وبجاه-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_938/nour_93810.mp3","categories":["التوسل والشفاعة"]}]
